/* Original worked examples. No textbook exercise or page numbers are asserted. */
(function(){
  'use strict';
  const s=String.raw;
  const make=(title,question,idea,steps,answer,commonErrors,difficulty=2,lab,visual)=>({title,question,idea,steps,answer,commonErrors,difficulty,source:{kind:'original',reference:'奥本海姆《信号与系统》第二版知识体系',page:null,exercise:null},...(lab?{lab}:{}),...(visual?{visual}:{})});
  const V=(domain,source,xmin=-3,xmax=3)=>({domain,source,xmin,xmax});
  const byTopic={
    'ct-dt':[
      make('从连续衰减到双边序列',s`将 $x_c(t)=e^{-|t|}$ 按 $T_s=1/2$ 采样，求 $x[n]$ 和 $x[-2],x[0],x[2]$。`,'先代入采样时刻，再处理负索引的绝对值。',[s`均匀采样定义为 $x[n]=x_c(nT_s)$。`,s`代入得 $x[n]=e^{-|n|/2}$，负索引并不表示信号不存在。`,s`当 $n=\pm2$ 时指数都是 $-1$，原点指数为 0。`],s`$x[n]=e^{-|n|/2}$；三点为 $e^{-1},1,e^{-1}$。`,['把负索引直接截成 0。'],1,'sampling',V('dt','exp(-abs(n)/2)',-6,6)),
      make('有限支撑如何变成样本集合',s`$x_c(t)=1$ 在 $1\le t<3$，其余为0。以 $T_s=1/2$ 采样，列出全部非零索引。`,'把时间区间转换为整数不等式。',[s`样本非零条件为 $1\le n/2<3$。`,s`乘2得 $2\le n<6$，随后只取整数。`,s`端点 $t=3$ 被排除，因此 $n=6$ 不在集合内。`],s`$x[n]=1$ 当 $n\in\{2,3,4,5\}$，其他索引为0。`,['忽略右端严格不等式，多取一个样本。'],1,'sampling'),
      make('离散时间与幅值量化是两件事',s`样本为 $[0.13,0.62,-0.38]$。再用 $Q(v)=0.25\operatorname{round}(v/0.25)$ 量化，求输出与最大绝对误差。`,'先保留时间离散，再单独计算幅值舍入。',[s`三个幅值除以0.25分别为 $0.52,2.48,-1.52$。`,s`舍入为 $1,2,-2$，再乘0.25。`,s`误差绝对值为 $0.12,0.12,0.12$，均不超过半个量化间隔0.125。`],s`量化结果 $[0.25,0.50,-0.50]$；最大误差0.12。`,['认为未经量化的离散序列也只能取整数幅值。'],1),
      make('同一序列可以来自不同连续信号',s`以 $f_s=8$ Hz 采样，说明 $\cos(2\pi t)$ 与 $\cos(2\pi9t)$ 为何给出同一序列。`,'比较采样时刻的相位差。',[s`第一序列为 $\cos(\pi n/4)$。`,s`第二序列为 $\cos(9\pi n/4)=\cos(\pi n/4+2\pi n)$。`,s`整数 $n$ 使额外相位为整圈，所以逐样本完全相同。`],s`两者均得到 $\cos(\pi n/4)$；仅凭样本无法判定原频率。`,['把两个连续波形相同与采样结果相同混为一谈。'],2,'sampling')
    ],
    'impulse-step':[
      make('用阶跃搭建分段常数信号',s`信号在 $t<0$ 为0、$0\le t<2$ 为3、$2\le t<4$ 为1、$t\ge4$ 为0。用阶跃表示并求分布导数。`,'每次跳变的增量就是阶跃或冲激的权重。',[s`在0处增加3，在2处减少2，在4处减少1。`,s`因此 $x=3u(t)-2u(t-2)-u(t-4)$。`,s`逐项求分布导数，把每个阶跃替换为同位置冲激。`],s`$x'=3\delta(t)-2\delta(t-2)-\delta(t-4)$。`,['把跳变后的高度当成跳变量。'],2,'transform'),
      make('冲激筛选与函数相乘',s`化简 $\cos(\pi t)\delta(t-3)$，再计算其全时间积分。`,'冲激只读取支点处的乘子。',[s`使用 $f(t)\delta(t-a)=f(a)\delta(t-a)$。`,s`$\cos(3\pi)=-1$，所以结果为 $-\delta(t-3)$。`,s`冲激积分等于其权重，故积分为 $-1$。`],s`化简为 $-\delta(t-3)$，积分 $-1$。`,['把冲激位置3误当成冲激权重3。'],1),
      make('反向尺度冲激的面积',s`计算 $\int (2t-1)\delta(3-2t)\,dt$，积分范围为整个实轴。`,'先提取仿射参数的绝对斜率。',[s`$3-2t=-2(t-3/2)$，故 $\delta(3-2t)=\tfrac12\delta(t-3/2)$。`,s`在支点 $t=3/2$，乘子 $2t-1=2$。`,s`筛选结果乘以面积系数 $1/2$。`],s`积分为1。`,['因斜率为负而给冲激添加负权重。'],2),
      make('离散阶跃的差分构造',s`令 $x[n]=u[n]-u[n-3]$，求 $x[n]-x[n-1]$。`,'把有限矩形视为两次阶跃跳变。',[s`$x[n]$ 在 $n=0,1,2$ 为1，其余为0。`,s`用 $u[n]-u[n-1]=\delta[n]$ 分别处理两组阶跃。`,s`开始位置增加1，结束后的第一拍 $n=3$ 减少1。`],s`$x[n]-x[n-1]=\delta[n]-\delta[n-3]$。`,['把下降沿放在最后一个非零样本 $n=2$。'],2,'transform',V('dt','u(n)-u(n-3)',-2,5))
    ],
    'exponential-sinusoid':[
      make('将复振荡恢复为实信号',s`求 $x(t)=(1+j)e^{j2t}+(1-j)e^{-j2t}$ 的实正弦形式。`,'先识别一对共轭项，再将复系数写成幅相。',[s`$1+j=\sqrt2e^{j\pi/4}$，另一项为其共轭。`,s`共轭复指数之和等于实部的2倍。`,s`所以幅度为 $2\sqrt2$，相位为 $\pi/4$。`],s`$x(t)=2\sqrt2\cos(2t+\pi/4)$。`,['忘记正负频率两项相加产生系数2。'],2),
      make('增长、旋转和幅值分别判断',s`对 $x(t)=3e^{(-0.4+j5)t}$，求 $|x(2)|$、相位增量及振荡周期。`,'实部管包络，虚部管相位，复指数本身并非衰减余弦。',[s`幅值为 $3e^{-0.4t}$，故 $|x(2)|=3e^{-0.8}$。`,s`从0到2相位增加 $5\times2=10$ rad。`,s`旋转一圈需要 $5T=2\pi$，但包络变化使整体非周期。`],s`幅值约1.34799；相位增加10 rad；振荡周期 $2\pi/5$。`,['把振荡周期当成整个阻尼信号的周期。'],1),
      make('负离散根带来的交替符号',s`分析 $x[n]=(-0.6)^nu[n]$，列前4项并写成幅度与离散振荡因子的乘积。`,'把负号写成每拍相位增量π。',[s`对整数 $n$，$(-1)^n=e^{j\pi n}$。`,s`因此 $(-0.6)^n=0.6^ne^{j\pi n}$，包络衰减。`,s`代入 $n=0,1,2,3$ 逐项计算。`],s`前4项为 $[1,-0.6,0.36,-0.216]$；包络 $0.6^n$。`,['因样本有负值而认为幅值也为负。'],1,'poles',V('dt','(-0.6)^n*u(n)',0,10)),
      make('采样后的复指数基底',s`将 $e^{(-2+j6)t}$ 按 $T_s=1/4$ 采样，写成 $z_0^n$ 并判断正向包络。`,'整个复频率先乘采样间隔。',[s`代入 $t=n/4$ 得 $e^{(-1/2+j3/2)n}$。`,s`所以 $z_0=e^{-1/2}e^{j3/2}$。`,s`其模 $e^{-1/2}<1$，因此随非负整数 $n$ 增大包络衰减。`],s`$z_0=e^{-1/2+j3/2}$，每拍包络倍率约0.60653。`,['只缩放虚部频率而忘记实部衰减率。'],2,'sampling')
    ],
    'periodicity':[
      make('连续谐波的共同周期',s`求 $x(t)=\sin(6t)+\cos(10t)$ 的基本周期。`,'找到两频率共同的最小正基频。',[s`两频率可写为 $3\times2$ 和 $5\times2$ rad/s。`,s`共同周期要求 $6T=2\pi k$、$10T=2\pi m$。`,s`由 $5k=3m$ 最小正整数解 $k=3,m=5$，得 $T=\pi$。`],s`基本周期 $T_0=\pi$。`,['取两个单独周期中较大的一个，而不检查共同重复。'],2,'fourier'),
      make('无理频率比破坏周期性',s`判断 $x(t)=\cos t+\cos(\sqrt2\,t)$ 是否周期。`,'非零不同频率成分必须共享同一个相位复位时刻。',[s`若存在共同周期，须有 $T=2\pi k$ 和 $\sqrt2T=2\pi m$。`,s`两式相除要求 $\sqrt2=m/k$。`,s`$\sqrt2$ 无理，不存在正整数 $k,m$；两独立频率分量不能共同重复。`],s`非周期。`,['认为任意两个周期信号相加都周期。'],2),
      make('离散频率先约分再求周期',s`求 $e^{j(14\pi/9)n}$ 的基本周期。`,'约分频率与2π的比值。',[s`$\omega_0/(2\pi)=7/9$，分子分母互素。`,s`要求 $7N/9$ 为整数。`,s`最小正整数 $N=9$；不是 $2\pi/\omega_0=9/7$。`],s`$N_0=9$。`,['把非整数 $9/7$ 当成离散索引周期。'],1),
      make('相位可能让序列退化',s`比较 $x[n]=\cos(\pi n)$ 与 $y[n]=\sin(\pi n)$ 的周期。`,'先计算整数索引上的实际值，再讨论最小周期。',[s`$x[n]=(-1)^n$，一拍变号，两拍恢复。`,s`对所有整数 $n$，$\sin(\pi n)=0$，所以 $y$ 是零序列。`,s`离散零序列的每个正整数都是周期，最小正整数周期为1。`],s`$x$ 基本周期2；$y$ 可取最小正整数周期1。`,['不看退化情况，直接给两序列都写周期2。'],2)
    ],
    'even-odd':[
      make('单边指数的奇偶部分',s`求 $x(t)=e^{-t}u(t)$ 的奇偶分量，原点取 $u(0)=1$。`,'先反转整个阶跃与指数，再相加减。',[s`$x(-t)=e^tu(-t)$。`,s`$x_e=[e^{-t}u(t)+e^tu(-t)]/2$。`,s`$x_o=[e^{-t}u(t)-e^tu(-t)]/2$；在原点两项相等，奇部为0。`],s`对 $t\ne0$，$x_e=\tfrac12e^{-|t|}$，$x_o=\tfrac12\operatorname{sgn}(t)e^{-|t|}$；另有 $x_e(0)=1$。`,['用几乎处处公式直接推出错误的原点值。'],3),
      make('有限序列的镜像分配',s`$x[-1]=2,x[0]=1,x[1]=4$，其余为0。求奇偶分量。`,'把成对索引的平均与半差分别计算。',[s`在 $n=\pm1$，偶分量都是 $(2+4)/2=3$。`,s`奇分量在 $n=1$ 为 $(4-2)/2=1$，在 $n=-1$ 为 $-1$。`,s`原点偶分量为1，奇分量为0，其余位置均为0。`],s`$x_e[-1,0,1]=[3,1,3]$；$x_o[-1,0,1]=[-1,0,1]$。`,['将奇分量两边都写成正值。'],1),
      make('复信号也能按时间对称分解',s`求 $x(t)=e^{j3t}$ 的普通奇偶分解，是否需要取共轭？`,'普通时间反转与共轭反转不是同一操作。',[s`仅反转时间得 $x(-t)=e^{-j3t}$。`,s`半和为 $\cos3t$，半差为 $j\sin3t$。`,s`$j\sin3t$ 仍满足 $x_o(-t)=-x_o(t)$，奇信号不必为实数。`],s`$x_e=\cos3t$，$x_o=j\sin3t$，不额外取共轭。`,['误用 $x^*(-t)$，使奇分量错误地变成0。'],2),
      make('用奇偶性压缩积分',s`求 $\int_{-2}^{2}(t^3+2t^2+1)dt$，说明为何可省去一项。`,'对称区间上的可积奇函数积分为0。',[s`$t^3$ 是奇项，在对称区间积分抵消。`,s`偶项积分为 $2\int_0^2(2t^2+1)dt$。`,s`计算得 $2(16/3+2)=44/3$。`],s`结果 $44/3$。`,['把整个非偶多项式直接写成两倍半区间积分。'],1)
    ],
    'time-transform':[
      make('仿射变换的支撑区间',s`原信号仅在 $-1<t<2$ 非零。求 $y(t)=x(-2t+3)$ 的非零区间。`,'直接解括号参数落在原支撑内的不等式。',[s`要求 $-1<-2t+3<2$。`,s`左式给 $t<2$，右式给 $t>1/2$；除负数时方向翻转。`,s`合并得到新区间，宽度由3压缩为1.5。`],s`$1/2<t<2$。`,['时间反转后忘记交换左右端点。'],1,'transform'),
      make('尺度与平移不交换',s`设 $D_1x(t)=x(t-1)$、$S_2x(t)=x(2t)$。比较 $S_2D_1x$ 与 $D_1S_2x$。`,'外层算子作用于内层形成的新函数。',[s`令 $g(t)=x(t-1)$，则 $S_2g(t)=g(2t)=x(2t-1)$。`,s`令 $h(t)=x(2t)$，则 $D_1h(t)=h(t-1)=x(2t-2)$。`,s`两者特征点分别映到 $t_0/2+1/2$ 和 $t_0/2+1$。`],s`一般 $S_2D_1\ne D_1S_2$。`,['把括号内减1视为变换后的统一延时1。'],2,'transform'),
      make('时间变换后的能量',s`已知 $E_x=6$，求 $y(t)=-3x(2t-4)$ 的能量。`,'幅度平方与时间测度缩放分开处理。',[s`$E_y=9\int|x(2t-4)|^2dt$。`,s`令 $v=2t-4$，则 $dt=dv/2$。`,s`平移不影响全时间积分，故 $E_y=(9/2)E_x$。`],s`$E_y=27$。`,['把幅度倍率3直接而非平方后用于能量。'],2),
      make('离散抽取与非整数索引',s`$x[n]$ 在 $n=0,1,2,3,4$ 取 $[1,2,3,4,5]$。求 $x[2n]$，并说明 $x[n/2]$ 是否已被定义。`,'先只读取合法整数索引，不擅自插值。',[s`$2n$ 必须落在原非零集合内，得到 $n=0,1,2$。`,s`相应样本为 $x[0],x[2],x[4]=1,3,5$。`,s`$n$ 为奇数时 $n/2$ 非整数，因此没有额外约定就不能定义整个 $x[n/2]$。`],s`抽取结果非零样本为 $[1,3,5]$；尺度扩展需另定插零或插值规则。`,['把连续时间的横轴缩放直接套到全部离散索引。'],2,'transform')
    ],
    'energy-power':[
      make('双边离散衰减的总能量',s`求 $x[n]=(1/2)^{|n|}$ 的能量与平均功率。`,'原点只计一次，两侧尾部用等比和。',[s`模平方为 $(1/4)^{|n|}$。`,s`$E=1+2\sum_{n=1}^{\infty}(1/4)^n=1+2/3$。`,s`能量有限，所以长窗口平均功率为0。`],s`$E=5/3$，$P=0$。`,['将原点在左右两条级数中重复计算。'],2),
      make('直流加正弦的周期功率',s`求 $x(t)=2+\cos3t$ 的平均功率。`,'展开平方后按一个完整周期平均。',[s`$|x|^2=4+4\cos3t+\cos^23t$。`,s`余弦均值为0，平方余弦均值为 $1/2$。`,s`三个平均相加，非零周期信号能量则发散。`],s`$P=9/2$，$E=\infty$。`,['把直流与正弦幅度先相加再平方。'],1),
      make('既非能量也非功率的例子',s`用定义分类 $x(t)=t\,u(t)$。`,'检查两个量各自是否有限，不从一个发散推断另一个。',[s`$E=\int_0^\infty t^2dt=\infty$。`,s`有限窗口平均为 $(2T)^{-1}\int_0^Tt^2dt=T^2/6$。`,s`该量随 $T\to\infty$ 也发散，不满足有限正功率条件。`],s`既非能量信号，也非功率信号。`,['认为所有非能量信号自动属于功率信号。'],1),
      make('有限复序列使用模平方',s`$x[0]=1+j,x[1]=2j$，其余为0。求能量，并比较直接平方的错误结果。`,'能量使用 $xx^*$，而不是 $x^2$。',[s`$|1+j|^2=1^2+1^2=2$。`,s`$|2j|^2=4$，所以总能量为6。`,s`直接平方会得 $(1+j)^2+(2j)^2=2j-4$，不是实非负能量。`],s`$E=6$，平均功率0。`,['对复信号漏掉复共轭。'],1)
    ],
    'complex-frequency':[
      make('第二象限相位不能只看反正切',s`求 $z=-1+j\sqrt3$ 的模与主相位。`,'先判象限，再给出 atan2 的角度。',[s`模为 $\sqrt{1+3}=2$。`,s`实部负、虚部正，位于第二象限。`,s`参考角为 $\pi/3$，主相位为 $\pi-\pi/3=2\pi/3$。`],s`$z=2e^{j2\pi/3}$。`,['直接算 arctan(−√3) 得到错误的第四象限角。'],1),
      make('两个滤波环节的幅相相加',s`$H_1=2e^{-j\pi/6}$、$H_2=3e^{j\pi/4}$，求级联复增益。`,'级联时复增益相乘，模乘相位加。',[s`幅度相乘为 $2\times3=6$。`,s`相位和为 $-\pi/6+\pi/4=\pi/12$。`,s`该相位已位于主值区间内，无需再包裹。`],s`$H=6e^{j\pi/12}$。`,['将级联幅度增益相加。'],1,'fourier'),
      make('采样频率单位转换',s`模拟角频率为 $120\pi$ rad/s，以600 Hz采样。求 Hz 频率、离散角频率与每周期样本数。`,'先除2π，再按采样间隔换算。',[s`$f=120\pi/(2\pi)=60$ Hz。`,s`$\omega_d=120\pi/600=\pi/5$ rad/sample。`,s`一个周期含 $600/60=10$ 个样本。`],s`60 Hz，$\pi/5$ rad/sample，10样本/周期。`,['把 rad/s 的数值直接当作 Hz 使用。'],1,'sampling'),
      make('频谱零点处为何不报告相位',s`$X(e^{j\omega})=1+e^{-j\omega}$，求 $\omega=0,\pi$ 处幅度，并讨论相位。`,'先计算复数本身，再判断相位是否有定义。',[s`在0处 $X=2$，幅度2，相位0。`,s`在π处 $X=1-1=0$，幅度0。`,s`零复数没有唯一辐角，不能把程序默认返回的0当成物理相位。`],s`幅度分别2与0；π处相位未定义。`,['在零幅值处强行给出相位0。'],2,'fourier')
    ],
    'linearity':[
      make('积分系统的完整叠加证明',s`证明 $T\{x\}(t)=\int_{t-1}^{t}x(\tau)d\tau$ 线性，输入取局部可积函数。`,'用积分的线性性比较两条路径。',[s`代入组合输入得到 $\int_{t-1}^t[ax_1(\tau)+bx_2(\tau)]d\tau$。`,s`积分区间只依赖输出时刻，不依赖输入，可拆成两个加权积分。`,s`拆开后恰为 $aT\{x_1\}(t)+bT\{x_2\}(t)$，对任意允许输入和标量成立。`],s`该系统线性。`,['仅用一个输入验证成功就当成普遍证明。'],2,'systems'),
      make('平方器一条反例足够',s`用齐次性检验 $T\{x\}=x^2$ 是否线性。`,'选常数输入与容易算的倍率。',[s`取 $x(t)=1$，则 $T\{x\}=1$。`,s`取倍率2，$T\{2x\}=4$。`,s`$2T\{x\}=2\ne4$，不满足必要的齐次性。`],s`平方器非线性。`,['零输入产生零输出只是必要条件，不是充分条件。'],1,'systems'),
      make('共轭系统：实线性还是复线性',s`$T\{x\}=x^*$。分别判断标量域为实数和复数时的线性。`,'共轭会同时作用于组合系数。',[s`一般 $T\{ax_1+bx_2\}=a^*x_1^*+b^*x_2^*$。`,s`若 $a,b$ 为实数，等于所需组合，因此实线性。`,s`若取 $a=j,x=1$，左侧为 $-j$，右侧为 $j$，复线性失败。`],s`实线性，但不复线性。`,['未说明允许的标量域。'],3,'systems'),
      make('非零初始值使映射成为仿射',s`系统满足 $y'+y=x$、固定 $y(0)=2$。输入到总输出的映射是否线性？`,'先用零输入测试必要条件。',[s`令 $x=0$，齐次方程解为 $y(t)=2e^{-t}$（$t\ge0$）。`,s`零输入产生非零输出，违反 $T\{0\}=0$。`,s`把初值清零后的零状态映射仍可线性；这里问的是固定非零初值下的总映射。`],s`总映射非线性（仿射）；零状态映射线性。`,['因方程对 y 和 x 只有一次项就忽略初值。'],3)
    ],
    'time-invariance':[
      make('固定长度滑动积分的时不变证明',s`判断 $T\{x\}(t)=\int_{t-1}^{t}x(v)dv$ 是否时不变。`,'路径A作积分变量替换，与整个输出平移比较。',[s`输入延时τ后，路径A为 $\int_{t-1}^{t}x(v-\tau)dv$。`,s`令 $r=v-\tau$，区间变成 $[t-\tau-1,t-\tau]$。`,s`这就是原输出在 $t-\tau$ 的值，所以两路径恒等。`],s`时不变。`,['看见积分上下限含 t 就直接判为时变。'],2,'systems'),
      make('固定起点积分器的边界效应',s`对全实轴信号定义 $T\{x\}(t)=\int_0^t x(v)dv$。用 $x(t)=1$ 与延时1判断时不变性。`,'固定下限0是绝对时间参照。',[s`原输出 $y(t)=t$。`,s`常数输入平移仍为1，路径A仍为 $t$。`,s`路径B为 $y(t-1)=t-1$，两者不相同。`],s`该固定起点映射时变。`,['把它与从负无穷积分的卷积积分器混为一谈。'],2,'systems'),
      make('离散调制器的两路径',s`判断 $T\{x\}[n]=(-1)^nx[n]$ 的时不变性，取延时1。`,'显式时变系数在两路径中出现不同索引。',[s`路径A为 $(-1)^nx[n-1]$。`,s`路径B为 $(-1)^{n-1}x[n-1]=-(-1)^nx[n-1]$。`,s`取 $x[n]=1$ 即得到不同输出，故一个整数移位反例已足够。`],s`时变；虽然延时2的检验会相等，也不能证明时不变。`,['只试偶数延时，漏掉奇数延时反例。'],2,'systems'),
      make('非线性与时不变可以同时成立',s`判断 $y(t)=|x(t)|$ 是否时不变。`,'时不变的比较与线性的比较是不同问题。',[s`路径A为 $|x(t-\tau)|$。`,s`路径B先求 $|x(t)|$ 再整体平移，也为 $|x(t-\tau)|$。`,s`两式对任意输入和τ相等；该结论不依赖绝对值运算是否线性。`],s`时不变，但通常非线性。`,['把非线性误当作必然时变。'],1,'systems')
    ],
    'causality':[
      make('混合过去与未来访问',s`判断 $y[n]=x[n-2]+x[n+1]$ 的因果性。`,'任一不可抵消的未来依赖就足以否定因果性。',[s`在 $n=0$，输出访问 $x[-2]$ 与 $x[1]$。`,s`选两序列在所有 $n\le0$ 相同，仅在 $n=1$ 相差1。`,s`当前输出随未来样本相差1，因此违反因果定义。`],s`非因果。`,['因为存在一个延时项，就认为整个系统因果。'],1,'systems'),
      make('乘时间系统不需要未来',s`判断 $y(t)=t^2x(t)$ 的因果性，并区分记忆性与时不变性。`,'系数在当前时刻已知，不属于未来输入。',[s`计算 $y(t_0)$ 只用 $x(t_0)$ 和已知数 $t_0^2$。`,s`若两输入过去和现在相同，当前输出必相同，所以因果。`,s`它无记忆；但两路径系数 $t^2$ 与 $(t-\tau)^2$ 一般不同，因此时变。`],s`因果、无记忆、时变。`,['把显式 t 与未来输入依赖混淆。'],2,'systems'),
      make('冲激响应支撑集直接判因果',s`LTI 系统 $h(t)=e^tu(-t)$，是否因果？构造一个具体的未来依赖。`,'在卷积中找出 h 负时间非零造成的输入访问。',[s`$h(t)$ 在 $t<0$ 非零，已违反因果 LTI 条件。`,s`卷积写为 $y(0)=\int x(\tau)h(-\tau)d\tau$。`,s`当 $\tau>0$ 时 $h(-\tau)=e^{-\tau}$ 非零，未来输入可改变当前输出。`],s`非因果；$y(0)$ 包含未来加权积分。`,['因为指数衰减而直接认定系统可实时实现。'],2,'convolution'),
      make('积分上限随当前时间回退',s`$y(t)=\int_{-\infty}^{t-2}x(v)e^{-(t-2-v)}dv$，对积分存在的输入判断因果性。`,'查看所有被访问的输入时刻是否不晚于现在。',[s`积分只涉及 $v\le t-2$。`,s`因为 $t-2<t$，所有输入均位于过去。`,s`因此任何在 $v\le t$ 相同的输入都会给出相同当前积分。`],s`因果，而且至少延时2。`,['把无限积分范围误认为一定包含未来。'],2,'systems')
    ],
    'bibo-stability':[
      make('有界非线性饱和器',s`判断 $T\{x\}(t)=x(t)/(1+|x(t)|)$ 的 BIBO 稳定性。`,'直接建立与输入时间无关的输出上界。',[s`令 $r=|x(t)|\ge0$，则 $|y|=r/(1+r)$。`,s`对所有有限 $r$，有 $0\le r/(1+r)<1$。`,s`所以每个有界输入都产生统一有界输出；非线性不妨碍BIBO稳定。`],s`BIBO稳定，$|y(t)|<1$。`,['误认为 BIBO 判据只适用于线性系统。'],1),
      make('绝对面积而非带符号面积',s`判断因果 $h(t)=\sin t\,u(t)$ 对应 LTI 系统是否 BIBO 稳定。`,'正负面积相互抵消不等于绝对面积有限。',[s`稳定充要条件要求 $\int_0^\infty|\sin t|dt$ 有限。`,s`每个长度π的区间绝对面积都是2。`,s`无限多个相同正面积相加发散，所以系统不稳定。`],s`非BIBO稳定。`,['使用 $\int h$ 的振荡抵消替代 $\int|h|$。'],2,'poles'),
      make('有限冲激列系统的增益上界',s`$y[n]=3x[n]-2x[n-1]+x[n-4]$，若 $|x[n]|\le M$，给出输出上界。`,'对各延时样本逐项应用三角不等式。',[s`$|y[n]|\le3|x[n]|+2|x[n-1]|+|x[n-4]|$。`,s`每个样本均不超过M，因此不超过 $6M$。`,s`上界与 n 无关，证明所有有界输入输出有界。`],s`$|y[n]|\le6M$，系统BIBO稳定。`,['将负系数按带符号相加得到错误上界2M。'],1,'systems'),
      make('非因果稳定的双边响应',s`求 $h[n]=2^{-|n|}$ 的绝对和并判断稳定与因果性。`,'双边衰减可以稳定，但负索引非零意味着非因果。',[s`$\sum|h[n]|=1+2\sum_{n=1}^\infty2^{-n}$。`,s`两侧尾部各为1，总和3，满足绝对可和。`,s`$h[-1]=1/2\ne0$，所以系统不是因果系统。`],s`绝对和3；BIBO稳定、非因果。`,['把稳定与因果当成同一个性质。'],2,'poles')
    ],
    'memory':[
      make('滑动窗口需要历史输入',s`$y[n]=(x[n]+x[n-1]+x[n-2])/3$ 是否有记忆？`,'构造当前值相同、过去值不同的输入。',[s`两序列在 $n=0$ 都取0。`,s`令第一序列在 $n=-1$ 为3，第二序列在该处为0，其他相关样本相同。`,s`两输出在0处相差1，因此仅当前输入值无法确定输出。`],s`有记忆，且因果。`,['因输出只平均有限项就称其无记忆。'],1),
      make('时变增益依然可以无记忆',s`$y[n]=\cos n\cdot x[n]$ 是否无记忆、因果？`,'只检查所需输入索引。',[s`在 $n_0$ 只访问 $x[n_0]$。`,s`$\cos n_0$ 是预先给定系数，不需要任何其他输入样本。`,s`故无记忆，也不需要未来输入，所以因果。`],s`无记忆、因果；一般时变。`,['把系统系数随时间变化误认为必须存储过去。'],1),
      make('先化简再判断记忆性',s`判断 $y[n]=x[n-1]-x[n-1]+4x[n]$ 的记忆性。`,'性质取决于实际映射，而非未化简表达式的外观。',[s`两个过去项对所有输入完全抵消。`,s`实际系统为 $y[n]=4x[n]$。`,s`输出仅依赖同一索引输入，因此无记忆。`],s`无记忆。`,['只要看见一个移位符号就判定有记忆。'],1),
      make('导数不是由单个当前值决定',s`在可微输入集合上，$y(t)=x'(t)$ 是否无记忆？`,'找在一点取值相同而斜率不同的两函数。',[s`选 $x_1(t)=0$、$x_2(t)=t$。`,s`在 $t=0$ 两者当前值都为0。`,s`导数分别为0和1，因此一个当前函数值不足以确定输出。`],s`有记忆。`,['把形式上写在同一个 t 处的导数误认作逐点函数。'],2)
    ],
    'invertibility':[
      make('指数逐点映射的指定定义域',s`实值输入经 $y(t)=e^{x(t)}$ 后是否可逆？若允许任意复值输入呢？`,'可逆性必须随允许的输入集合一起声明。',[s`实指数在实数轴严格单调，输出为正时可用 $x=\ln y$ 恢复。`,s`复输入中 $e^{x+j2\pi}=e^x$。`,s`因此不同复输入会产生同一输出，任意复输入集合上不可逆。`],s`实值输入上可逆；任意复值输入上不可逆。`,['忽略复指数的2πj周期性。'],3),
      make('延时的逆可能需要未来',s`$y(t)=-2x(t-3)$，求逆映射并判断逆系统因果性。`,'先把输出时间改为 t+3，再解输入。',[s`$y(t+3)=-2x(t)$。`,s`所以 $x(t)=-y(t+3)/2$，唯一恢复全部输入。`,s`逆映射在当前时刻需要未来输出值 $y(t+3)$，因此非因果。`],s`可逆；逆为 $x(t)=-\tfrac12y(t+3)$，非因果。`,['数学可逆就必然能够无延迟实时求逆。'],2,'transform'),
      make('差分器丢失直流信息',s`$y[n]=x[n]-x[n-1]$，在所有双边序列上是否可逆？`,'寻找两输入只相差常数的情况。',[s`取 $x_1[n]=0$ 和 $x_2[n]=5$。`,s`常数序列相邻两拍相等，因此两者的一阶差分都恒为0。`,s`因此输出不能确定输入中的直流常数；若额外给定初始值，有限起点递推可恢复。`],s`在全部双边序列上不可逆。`,['未给初值就直接对差分累加并认定恢复唯一。'],2),
      make('累加器在零状态条件下可求逆',s`对 $n\ge0$，$y[n]=\sum_{k=0}^{n}x[k]$，约定 $y[-1]=0$。求逆并验证首拍。`,'相邻两个部分和相减只留下新增样本。',[s`$y[n-1]=\sum_{k=0}^{n-1}x[k]$（$n\ge1$）。`,s`相减得 $x[n]=y[n]-y[n-1]$。`,s`$n=0$ 时利用约定 $y[-1]=0$，仍有 $x[0]=y[0]$。`],s`逆系统为一阶差分，且因果。`,['忽略首拍边界条件。'],2)
    ]
  };
  Object.assign(byTopic,{
    'impulse-response':[
      make('由阶跃响应反推冲激响应',s`因果LTI的阶跃响应为 $g(t)=(1-e^{-2t})u(t)$，求冲激响应。`,'阶跃是冲激的积分，零状态阶跃响应求导得到冲激响应。',[s`$h=g'$，在分布意义下对乘积求导。`,s`普通部分导数为 $2e^{-2t}u(t)$。`,s`原点冲激系数为 $1-e^0=0$，所以没有额外冲激项。`],s`$h(t)=2e^{-2t}u(t)$。`,['乘阶跃求导时完全漏检原点冲激项。'],2,'convolution'),
      make('离散冲激响应与单位延时',s`零状态系统 $y[n]=x[n]-3x[n-2]$，求 $h[n]$，再求输入 $x[n]=\delta[n+1]$ 的输出。`,'先代入单位冲激，再利用时不变性整体移位。',[s`单位冲激输入给 $h[n]=\delta[n]-3\delta[n-2]$。`,s`$\delta[n+1]$ 比单位冲激提前1拍。`,s`输出同样提前1拍，为 $h[n+1]$。`],s`输出 $\delta[n+1]-3\delta[n-1]$。`,['把提前输入误作延迟输出。'],1,'convolution'),
      make('非LTI系统不能只看一条冲激响应',s`离散系统 $T_1\{x\}[n]=x[n]$ 与 $T_2\{x\}[n]=x^2[n]$ 对单位冲激输出相同，是否说明系统相同？`,'使用普通输入区分映射；不对连续Dirac作平方。',[s`离散冲激仅取0和1，因此 $\delta^2[n]=\delta[n]$。`,s`两系统对该输入都输出 $\delta[n]$。`,s`取 $x[n]=2\delta[n]$，两输出分别为 $2\delta[n]$ 和 $4\delta[n]$。`],s`系统不同；只有满足LTI等条件时单个冲激响应才足以描述零状态映射。`,['将离散Kronecker平方的结论套给连续Dirac平方。'],2),
      make('从输入冲激分解求三角响应',s`$h[n]=u[n]-u[n-3]$，输入 $x[n]=\delta[n]+\delta[n-1]+\delta[n-2]$。求全部输出非零样本。`,'把每个输入冲激变成一份移位矩形响应。',[s`由线性时不变性，$y=h[n]+h[n-1]+h[n-2]$。`,s`三份长度3的矩形在0到4拍逐次重叠。`,s`各位置的重叠数依次为 $1,2,3,2,1$。`],s`$y[0..4]=[1,2,3,2,1]$，其余为0。`,['把输入各冲激的高度相加后只画一份矩形。'],2,'convolution')
    ],
    'ct-convolution':[
      make('不同宽度矩形产生梯形',s`$x=\mathbf1_{[0,2]}$、$h=\mathbf1_{[0,1]}$，求卷积。`,'输出等于两支撑区间的重叠长度。',[s`积分变量需同时满足 $0\le\tau\le2$ 和 $t-1\le\tau\le t$。`,s`$0<t<1$ 时重叠长度t；$1\le t\le2$ 时完整重叠长度1。`,s`$2<t<3$ 时长度为 $3-t$，其他时刻无正长度交集。`],s`$y=t$（0到1），$y=1$（1到2），$y=3-t$（2到3），带外0。`,['认为任何两个矩形卷积都必须是三角形。'],2,'convolution'),
      make('两个阶跃的卷积是否存在',s`求 $u(t)*u(t)$，并解释结果增长是否违反卷积定义。`,'固定t后只积分真正重叠的有限区间。',[s`$t<0$ 时 $\tau\ge0$ 与 $\tau\le t$ 不可能同时满足。`,s`$t\ge0$ 时被积函数在 $0\le\tau\le t$ 为1。`,s`积分为t；每个固定t的积分有限，但输出随t增长。`],s`$y(t)=t\,u(t)$。`,['把每个时刻积分存在与系统BIBO稳定混为一谈。'],1,'convolution'),
      make('正弦与阶跃的累积响应',s`求 $\sin(t)u(t)*u(t)$。`,'支撑集给区间，普通积分给解析式。',[s`两信号均因果，因此 $t\ge0$ 时积分从0到t。`,s`选变量使 $y=\int_0^t\sin\tau\,d\tau$。`,s`积分得 $1-\cos t$，负时间输出为0。`],s`$y(t)=(1-\cos t)u(t)$。`,['只写不定积分 −cos t 而漏掉下限常数。'],1,'convolution'),
      make('有限脉冲经过一阶系统',s`$x=u(t)-u(t-2)$，$h=e^{-t}u(t)$。求分段输出。`,'把脉冲拆成两个延迟阶跃响应。',[s`单位阶跃响应为 $g=(1-e^{-t})u(t)$。`,s`所以 $y=g(t)-g(t-2)$。`,s`在 $0\le t<2$ 仅第一项存在；$t\ge2$ 两项相减得 $e^{-(t-2)}-e^{-t}$。`],s`$y=0$（t<0），$1-e^{-t}$（0≤t<2），$(e^2-1)e^{-t}$（t≥2）。`,['在输入关断后把系统输出立即设为0。'],2,'convolution',V('ct','u(t)-u(t-2)',-1,5))
    ],
    'dt-convolution':[
      make('有符号短序列逐项卷积',s`$x[0..1]=[2,-1]$、$h[0..1]=[1,3]$。求线性卷积。`,'输出索引是两个输入索引之和。',[s`$y[0]=2\times1=2$。`,s`$y[1]=2\times3+(-1)\times1=5$。`,s`$y[2]=(-1)\times3=-3$，其余为0。`],s`$y[0..2]=[2,5,-3]$。`,['漏掉中间输出的两项重叠。'],1,'convolution'),
      make('指数与阶跃的卷积和',s`求 $(0.4)^nu[n]*u[n]$。`,'固定输出n后用有限等比级数，而非无限和。',[s`$n<0$ 时没有重叠。`,s`$n\ge0$ 时 $y[n]=\sum_{k=0}^{n}0.4^k$。`,s`有限等比公式给 $[1-0.4^{n+1}]/(1-0.4)$。`],s`$y[n]=\frac53(1-0.4^{n+1})u[n]$。`,['把有限上限直接换成无穷而丢掉暂态项。'],2,'convolution'),
      make('序列的起始索引必须保留',s`$x[-1]=1,x[0]=2$，$h[2]=3,h[3]=1$，其余为0。求输出。`,'同时计算数值与输出起始索引。',[s`最早贡献索引为 $-1+2=1$，值为3。`,s`在2拍两项相加得 $1\times1+2\times3=7$。`,s`在3拍值为 $2\times1=2$，没有其他贡献。`],s`$y[1]=3,y[2]=7,y[3]=2$，其余为0。`,['默认所有有限数组都从索引0起。'],2),
      make('卷积和并非对任意序列存在',s`令 $x[n]=u[n]$、$h[n]=u[-n-1]$，判断普通卷积和是否有限。`,'查看固定n时有多少个非零乘积。',[s`$x[k]\ne0$ 要求 $k\ge0$。`,s`$h[n-k]=u[k-n-1]$ 非零要求 $k\ge n+1$。`,s`对全部 $k\ge\max(0,n+1)$，乘积都为1，存在无穷多正项。`],s`每个n处求和都发散，普通卷积和不存在有限值。`,['没有检查收敛就机械套卷积性质。'],3)
    ],
    'convolution-properties':[
      make('串联延时与差分器',s`$h_1[n]=\delta[n]-\delta[n-1]$，$h_2[n]=2\delta[n-3]$，求串联等效响应。`,'与移位冲激卷积就是延时并缩放。',[s`$h_{eq}=h_1*h_2$。`,s`$h_2$ 使整条 $h_1$ 延时3拍并放大2。`,s`对两冲激分别应用该变换。`],s`$h_{eq}=2\delta[n-3]-2\delta[n-4]$。`,['把串联响应直接逐点相乘。'],1,'convolution'),
      make('卷积总面积的检查法',s`若 $x,h$ 绝对可积，且 $\int x=2$、$\int h=-3$，求 $\int(x*h)$。`,'在可交换积分的条件下分解二重积分。',[s`写 $\int_t\int_\tau x(\tau)h(t-\tau)d\tau dt$。`,s`绝对可积允许交换积分，内层令 $v=t-\tau$ 得 $\int h(v)dv$。`,s`外层只剩 $\int x$，所以总面积为两个面积之积。`],s`总面积 $-6$。`,['把总面积误当成输出总能量；两者公式不同。'],2),
      make('支撑集相加只是包含关系',s`$x=\delta[n]-\delta[n-1]$、$h=\delta[n]+\delta[n-1]$。计算卷积，解释输出中间点为何消失。`,'展开并检查同一位置的正负贡献。',[s`四个卷积项分别位于0、1、1、2。`,s`一拍处的系数为 $1-1=0$。`,s`于是输出仅在0、2拍非零；支撑可能因抵消小于索引和集合。`],s`$x*h=\delta[n]-\delta[n-2]$。`,['认为支撑的闵可夫斯基和中每一点都必非零。'],2),
      make('并联后接串联的等效系统',s`并联支路为 $h_1=\delta[n]$、$h_2=\delta[n-1]$，随后串联 $g=\delta[n]-\delta[n-2]$。求等效响应。`,'先相加支路，再用分配律卷积。',[s`并联合成为 $h_p=\delta[n]+\delta[n-1]$。`,s`$h_{eq}=h_p*g=g[n]+g[n-1]$。`,s`展开成四个不同时刻的冲激。`],s`$h_{eq}=\delta[n]+\delta[n-1]-\delta[n-2]-\delta[n-3]$。`,['混淆并联相加与串联卷积。'],2,'convolution')
    ],
    'differential-difference':[
      make('积分因子解一阶微分方程',s`$y'+3y=6u(t)$，$y(0^-)=0$，求 $t\ge0$ 响应。`,'给出积分因子的完整步骤，而不是直接背稳态式。',[s`对 $t>0$ 两侧乘 $e^{3t}$，左侧为 $(e^{3t}y)'$。`,s`从0到t积分得 $e^{3t}y(t)-0=6(e^{3t}-1)/3$。`,s`乘回 $e^{-3t}$，并检查初值0、稳态2。`],s`$y(t)=2(1-e^{-3t})$（t≥0）。`,['特解2没有满足零初始值，还需自然响应。'],2),
      make('二阶差分的自然模式',s`零输入方程 $y[n]-y[n-1]+0.24y[n-2]=0$，已知 $y[0]=1,y[1]=0.6$，求 $n\ge0$ 解。`,'特征根给模式，两个初值确定系数。',[s`特征多项式 $r^2-r+0.24=(r-0.6)(r-0.4)$。`,s`通解 $C(0.6)^n+D(0.4)^n$。`,s`初值给 $C+D=1$、$0.6C+0.4D=0.6$，解得 $C=1,D=0$。`],s`$y[n]=(0.6)^n$。`,['只用一个初值就试图确定两个自然模式系数。'],2,'poles'),
      make('递推求有限输入的前几拍',s`$y[n]=0.5y[n-1]+x[n]$，$y[-1]=0$，输入 $x[0..2]=[1,-1,2]$，其余为0。求 $y[0..4]$。`,'从已给边界逐拍代入。',[s`$y[0]=1$，$y[1]=0.5-1=-0.5$。`,s`$y[2]=0.5(-0.5)+2=1.75$。`,s`此后输入为0，逐拍减半，得到0.875与0.4375。`],s`$[1,-0.5,1.75,0.875,0.4375]$。`,['输入结束后把递归系统的输出也置零。'],1),
      make('方程没有初值时解不唯一',s`仅给 $y'+y=0$，能否唯一确定输出？比较两种初值。`,'把自由常数明确保留下来。',[s`分离变量或特征法给 $y(t)=Ce^{-t}$。`,s`$y(0)=0$ 对应零解；$y(0)=2$ 对应 $2e^{-t}$。`,s`二者都满足同一方程，因此输入输出方程本身没有给足边界信息。`],s`不能唯一确定；需要初始或其他边界条件。`,['默认所有未说明的初值都为0。'],1)
    ],
    'zero-input-state':[
      make('离散冲激与非零储能相加',s`$y[n]-0.25y[n-1]=\delta[n]$（n≥0），$y[-1]=4$，分解两类响应。`,'保留初值时关输入，保留输入时清初值。',[s`零输入首拍为 $0.25\times4=1$，故 $y_{zi}[n]=0.25^n$。`,s`零状态冲激响应也是 $y_{zs}[n]=0.25^n$。`,s`线性相加得到 $2(0.25)^n$，首拍总输出2符合递推。`],s`$y_{zi}=y_{zs}=0.25^n$，总响应 $2(0.25)^n$（n≥0）。`,['将 $y[-1]=4$ 直接当成零输入响应在0拍的值。'],2),
      make('无外部输入仍会有输出',s`RC型系统 $y'+4y=0$，$y(0^-)=5$。给出零输入、零状态、总响应。`,'判断每一部分的激励来源。',[s`外部输入为0，所以零状态响应恒为0。`,s`初始储能不为0，齐次方程给 $y_{zi}=5e^{-4t}$。`,s`总响应等于零输入响应，随正时间衰减。`],s`$y_{zi}=5e^{-4t},y_{zs}=0,y=5e^{-4t}$（t≥0）。`,['把“零输入”误解为没有任何响应。'],1),
      make('原点冲激引起状态跳变',s`$y'+y=3\delta(t)$，$y(0^-)=2$。求 $y(0^+)$ 与正时间响应。`,'先在原点两侧积分，再解正时间齐次方程。',[s`在 $[-\varepsilon,\varepsilon]$ 积分，普通有限状态的积分项趋于0。`,s`得到 $y(0^+)-y(0^-)=3$，所以 $y(0^+)=5$。`,s`$t>0$ 无外部输入，故 $y=5e^{-t}$；也可分成 $2e^{-t}+3e^{-t}$。`],s`$y(0^+)=5$，$y(t)=5e^{-t}$（t>0）。`,['含冲激时仍强行令 $0^-$ 与 $0^+$ 相等。'],3),
      make('输入与自然模式同频时',s`$y'+y=e^{-t}$（t≥0），$y(0)=2$。求零输入、零状态与总响应。`,'用积分因子，识别共振产生的时间因子。',[s`零输入为 $2e^{-t}$。`,s`零状态满足 $(e^ty_{zs})'=1$，零初值积分得 $y_{zs}=te^{-t}$。`,s`相加得 $(2+t)e^{-t}$，代回方程右侧确为 $e^{-t}$。`],s`总响应 $(2+t)e^{-t}$（t≥0）。`,['受迫指数与自然指数相同时仍只假设常数倍指数特解。'],2)
    ],
    'response-methods':[
      make('接通余弦包含暂态',s`零状态 $y'+y=\cos(t)u(t)$。求 $t\ge0$ 的完整输出。`,'先找正弦特解，再用初值补齐自然模式。',[s`设特解 $A\cos t+B\sin t$，代入得 $A+B=1,B-A=0$。`,s`所以特解为 $(\cos t+\sin t)/2$。`,s`加 $Ce^{-t}$ 并用 $y(0)=0$ 得 $C=-1/2$。`],s`$y=(\cos t+\sin t-e^{-t})/2$（t≥0）。`,['只给正弦稳态，漏掉接通暂态。'],2),
      make('离散交替输入的完整响应',s`零状态 $y[n]-0.5y[n-1]=(-1)^nu[n]$。求 n≥0 响应。`,'用交替特解与指数齐次项，并检查首拍。',[s`设特解 $C(-1)^n$，代入得 $1.5C=1$，故 $C=2/3$。`,s`齐次项为 $D(0.5)^n$。`,s`零状态首拍 $y[0]=1$，所以 $D=1/3$。`],s`$y[n]=\tfrac23(-1)^n+\tfrac13(0.5)^n$（n≥0）。`,['将持续交替输入的频率响应当成接通后的全部输出。'],2),
      make('多项式指数卷积',s`求 $e^{-t}u(t)*te^{-t}u(t)$。`,'相同指数可以提出积分外，剩下低阶多项式积分。',[s`$t\ge0$ 时积分为 $\int_0^t e^{-\tau}(t-\tau)e^{-(t-\tau)}d\tau$。`,s`提出 $e^{-t}$，剩 $\int_0^t(t-\tau)d\tau=t^2/2$。`,s`负时间没有重叠，补上阶跃。`],s`$y(t)=\tfrac12t^2e^{-t}u(t)$。`,['将两函数逐点相乘误作 $te^{-2t}$。'],2,'convolution'),
      make('复指数特征函数也有收敛条件',s`$h=e^{-t}u(t)$，输入为全实轴上的 $e^{-t/2}$。求输出；再解释全实轴输入 $e^{-2t}$ 为何不能同法形式代入。`,'先检查卷积的指数积分是否收敛。',[s`第一输入给 $y=e^{-t/2}\int_0^\infty e^{-\tau/2}d\tau=2e^{-t/2}$。`,s`该特征值对应 $s_0=-1/2$，位于 $H(s)=1/(s+1)$ 的 ROC 实部大于−1内。`,s`第二输入使内层成为 $\int_0^\infty e^{\tau}d\tau$，发散；形式值 $H(-2)$ 不代表存在输出。`],s`第一输出 $2e^{-t/2}$；第二卷积发散。`,['忽略输入是否双边存在及特征频率是否位于ROC。'],3)
    ],
    'ctfs':[
      make('相移正弦余弦的复系数',s`$x(t)=1+2\cos(3t+\pi/3)+\sin6t$，以 $\omega_0=3$ 求非零CTFS系数。`,'逐项用欧拉公式定位谐波编号。',[s`直流给 $a_0=1$。`,s`余弦项给 $a_1=e^{j\pi/3},a_{-1}=e^{-j\pi/3}$。`,s`$\sin6t=(e^{j2\omega_0t}-e^{-j2\omega_0t})/(2j)$，所以 $a_2=-j/2,a_{-2}=j/2$。`],s`仅 $k=0,\pm1,\pm2$ 非零，系数如步骤。`,['把幅度2余弦的每条复谱线也写成2。'],2,'fourier'),
      make('四分之一占空比脉冲列',s`周期4，信号在每周期居中的 $|t|<1/2$ 为1，其余为0。求 $a_0,a_k$。`,'在一个周期只积分非零区间。',[s`基频 $\omega_0=\pi/2$，直流为面积/周期 $a_0=1/4$。`,s`$k\ne0$ 时 $a_k=\tfrac14\int_{-1/2}^{1/2}e^{-jk\pi t/2}dt$。`,s`积分得 $a_k=\sin(k\pi/4)/(k\pi)$，也等于 $\tfrac14\operatorname{sinc}(k/4)$。`],s`$a_0=1/4$；$a_k=\sin(k\pi/4)/(k\pi)$（k≠0）。`,['把脉冲宽1与周期4混淆，漏掉1/4归一化。'],2),
      make('锯齿波的奇对称系数',s`$x(t)=t$（$-\pi<t<\pi$）并作2π周期延拓，求CTFS系数。`,'奇性先消除直流和余弦，再做一次分部积分。',[s`函数奇对称，$a_0=0$，$a_k$ 应为纯虚数。`,s`$\int_{-\pi}^{\pi}t\sin(kt)dt=-2\pi(-1)^k/k$（k≠0）。`,s`在 $a_k=(2\pi)^{-1}\int t[\cos kt-j\sin kt]dt$ 中代入。`],s`$a_k=j(-1)^k/k$（k≠0），$a_0=0$。`,['积分分部时漏掉周期端点的边界项。'],3),
      make('平移对级数系数的作用',s`已知周期为6的 $x(t)$ 的系数为 $a_k$。求 $y(t)=x(t-1)$ 的系数，并说明幅度是否改变。`,'将平移作用到每个谐波的指数上。',[s`基频为 $\omega_0=\pi/3$。`,s`$e^{jk\omega_0(t-1)}=e^{-jk\pi/3}e^{jk\omega_0t}$。`,s`所以 $b_k=a_ke^{-jk\pi/3}$，乘子模为1。`],s`$b_k=a_ke^{-jk\pi/3}$；$|b_k|=|a_k|$。`,['把整个系数序列沿k轴平移。'],1,'fourier')
    ],
    'dtfs':[
      make('三点周期的直接分析',s`周期3序列一个周期为 $[1,1,0]$，求3个独立DTFS系数。`,'按分析式的1/N归一化逐频率代入。',[s`$a_k=(1+e^{-j2\pi k/3})/3$。`,s`$a_0=2/3$；$e^{-j2\pi/3}=-1/2-j\sqrt3/2$。`,s`所以 $a_1=1/6-j\sqrt3/6$，实序列保证 $a_2=a_1^*$。`],s`$[a_0,a_1,a_2]=[2/3,(1-j\sqrt3)/6,(1+j\sqrt3)/6]$。`,['用DFT未归一化结果冒充这里的DTFS系数。'],2),
      make('离散调制循环移动系数',s`$x[n]$ 为N周期、系数 $a_k$。令 $y[n]=e^{j2\pi mn/N}x[n]$，求 $b_k$。`,'合成式中指数次数相加，系数索引按N循环。',[s`$y=\sum_k a_ke^{j2\pi(k+m)n/N}$。`,s`令新编号 $r=k+m$，对应系数为 $a_{r-m}$。`,s`由于谐波只分N类，索引应按模N理解。`],s`$b_k=a_{(k-m)\bmod N}$。`,['把DTFS系数平移时忽略循环回绕。'],2),
      make('奈奎斯特谐波的正负编号重合',s`$x[n]=\cos(\pi n)$，取N=2，求DTFS系数。`,'正负π离散复指数实际相同，不能留下两条独立谱线。',[s`$e^{j\pi n}=e^{-j\pi n}=(-1)^n$。`,s`两条欧拉项各权重1/2，但都属于 $k=1\pmod2$。`,s`因此系数合并为1，直流系数为0。`],s`$a_0=0,a_1=1$。`,['保留两条独立的1/2系数，导致独立系数数目错误。'],2),
      make('用DTFS Parseval求功率',s`N=4，只有 $a_0=1,a_1=j$ 非零，求平均功率并用样本验证。`,'一个周期平均模平方等于系数模平方之和。',[s`$P=|1|^2+|j|^2=2$。`,s`合成为 $x[n]=1+je^{j\pi n/2}$，一个周期为 $[1+j,0,1-j,2]$。`,s`样本模平方和为 $2+0+2+4=8$，除4同样得2。`],s`$P=2$。`,['使用普通平方而非复模平方。'],2)
    ],
    'ctft':[
      make('双边指数的连续频谱',s`求 $x(t)=e^{-2|t|}$ 的CTFT。`,'在原点分成左右两段，分别使用收敛指数积分。',[s`右半轴贡献 $\int_0^\infty e^{-(2+j\omega)t}dt=1/(2+j\omega)$。`,s`左半轴贡献 $\int_{-\infty}^0e^{(2-j\omega)t}dt=1/(2-j\omega)$。`,s`相加并通分，虚部抵消，得到实偶频谱。`],s`$X(j\omega)=4/(4+\omega^2)$。`,['遗漏负时间一半，使频谱不再实偶。'],2,'fourier'),
      make('不居中的矩形附带线性相位',s`$x(t)=1$ 在 $1<t<3$，其余为0。求CTFT。`,'先移到中心，再使用矩形变换对。',[s`宽度2、中心2，因此 $x(t)=\operatorname{rect}((t-2)/2)$。`,s`居中宽2矩形变换为 $2\sin\omega/\omega$，零点处取极限。`,s`延时2乘以 $e^{-j2\omega}$。`],s`$X(j\omega)=2e^{-j2\omega}\sin\omega/\omega$，$X(0)=2$。`,['只给sinc幅度谱，漏掉矩形位置引起的相位。'],2),
      make('有限冲激组合的频谱',s`求 $x(t)=2\delta(t+1)-\delta(t-2)$ 的CTFT及零频值。`,'各冲激按位置贡献复指数。',[s`$\delta(t-t_0)$ 对应 $e^{-j\omega t_0}$。`,s`提前1的项贡献 $2e^{j\omega}$，延时2的项贡献 $-e^{-j2\omega}$。`,s`零频两指数均为1，总值为1，与总权重一致。`],s`$X=2e^{j\omega}-e^{-j2\omega}$；$X(0)=1$。`,['在冲激筛选时把时间平移的相位符号写反。'],1),
      make('时间乘法生成重复频域分母',s`由 $e^{-t}u(t)\leftrightarrow1/(1+j\omega)$ 求 $te^{-t}u(t)$ 的CTFT。`,'使用对频率求导性质，并保留j系数。',[s`变换定义给 $dX/d\omega=\int(-jt)x(t)e^{-j\omega t}dt$。`,s`因此 $\mathcal F\{tx\}=j\,dX/d\omega$。`,s`$j[-j/(1+j\omega)^2]=1/(1+j\omega)^2$。`],s`$\mathcal F\{te^{-t}u(t)\}=1/(1+j\omega)^2$。`,['频率求导后忘记乘j。'],2)
    ],
    'dtft':[
      make('短对称序列的幅相',s`$x[0..2]=[1,2,1]$，求DTFT及非零频点的相位形式。`,'先因式分解，再提出居中延时。',[s`$X=1+2e^{-j\omega}+e^{-j2\omega}=(1+e^{-j\omega})^2$。`,s`$1+e^{-j\omega}=2e^{-j\omega/2}\cos(\omega/2)$。`,s`故 $X=4e^{-j\omega}\cos^2(\omega/2)$，非零处相位为 $-\omega\pmod{2\pi}$。`],s`幅度 $4\cos^2(\omega/2)$；奇数π处为零，相位未定义。`,['在平方余弦非负时额外添加错误的π相位翻转。'],2,'fourier'),
      make('左边衰减序列的DTFT',s`$x[n]=(1/2)^{-n}u[-n-1]$，求DTFT。`,'用m=−n把负索引变成正向等比级数。',[s`非零索引为 $n\le-1$，令 $m=-n\ge1$。`,s`$X=\sum_{m=1}^{\infty}(0.5e^{j\omega})^m$。`,s`比值模为0.5，求和得首项除以1减比值。`],s`$X=0.5e^{j\omega}/(1-0.5e^{j\omega})$。`,['将左边信号直接套用右边序列的负指数频谱。'],2),
      make('两拍差分形成多个频谱零点',s`$h[n]=\delta[n]-\delta[n-2]$，求DTFT并找 $[-\pi,\pi]$ 内零点。`,'利用指数差的正弦分解。',[s`$H=1-e^{-j2\omega}=2je^{-j\omega}\sin\omega$。`,s`幅度为 $2|\sin\omega|$。`,s`零点要求 $\sin\omega=0$，区间内为 $-\pi,0,\pi$。`],s`$H=1-e^{-j2\omega}$；零点如步骤。`,['只检查直流零点，漏掉π处对交替样本的抵消。'],1,'fourier'),
      make('周期矩形频谱的逆DTFT',s`令 $H(e^{j\omega})=1$ 在 $|\omega|<\pi/2$、其余基本区间为0，并作2π周期延拓。求 $h[n]$。`,'逆变换只在通带积分，n=0单独处理。',[s`$h[n]=(2\pi)^{-1}\int_{-\pi/2}^{\pi/2}e^{j\omega n}d\omega$。`,s`$n\ne0$ 时得到 $\sin(\pi n/2)/(\pi n)$。`,s`$n=0$ 时积分为通带宽π除以2π，得到1/2。`],s`$h[0]=1/2$，$h[n]=\sin(\pi n/2)/(\pi n)$（n≠0）。`,['把连续逆变换积分范围与离散周期频谱的单周期积分混淆。'],3,'fourier')
    ],
    'fourier-properties':[
      make('尺度变换同时改变谱宽与高度',s`已知 $x(t)=e^{-|t|}$、$X=2/(1+\omega^2)$，求 $y(t)=x(3t)$ 的频谱。`,'使用绝对尺度系数，频率变量替换为ω/3。',[s`尺度性质给 $Y=(1/3)X(j\omega/3)$。`,s`代入得到 $(2/3)/(1+\omega^2/9)$。`,s`化简为 $6/(9+\omega^2)$，零频值2/3与新时域面积一致。`],s`$Y=6/(9+\omega^2)$。`,['只扩展频率轴而漏掉高度系数1/3。'],2),
      make('余弦调制把基带复制两份',s`$x(t)\leftrightarrow X(j\omega)$，求 $x(t)\cos5t$ 的CTFT。`,'把载波拆成两个方向的复指数。',[s`$\cos5t=(e^{j5t}+e^{-j5t})/2$。`,s`正频率调制给 $X(j(\omega-5))$，负频率调制给 $X(j(\omega+5))$。`,s`按线性性相加，并为每份保留1/2。`],s`$Y=\tfrac12[X(j(\omega-5))+X(j(\omega+5))]$。`,['将两份频谱的高度都保留为原高度。'],1,'fourier'),
      make('矩形导数验证jω性质',s`$x(t)=u(t)-u(t-2)$，用两种方法求 $x'(t)$ 的CTFT。`,'分布求导和频率乘jω应给出一致结果。',[s`$x'=\delta(t)-\delta(t-2)$，直接变换为 $1-e^{-j2\omega}$。`,s`原信号 $X=(1-e^{-j2\omega})/(j\omega)$，零频按极限。`,s`乘 $j\omega$ 得到同一表达式，在零频为0。`],s`$\mathcal F\{x'\}=1-e^{-j2\omega}=j\omega X$。`,['对跳变矩形只取普通导数0而漏掉冲激。'],2),
      make('离散交替调制对应π平移',s`$x[n]=(1/3)^nu[n]$，求 $y[n]=(-1)^nx[n]$ 的DTFT。`,'把交替因子写成e的jπn次方。',[s`原谱为 $X=1/(1-\tfrac13e^{-j\omega})$。`,s`$(-1)^n=e^{j\pi n}$，故 $Y(\omega)=X(\omega-\pi)$。`,s`代入 $e^{-j(\omega-\pi)}=-e^{-j\omega}$。`],s`$Y=1/(1+\tfrac13e^{-j\omega})$。`,['把调制误认为时间延迟。'],2)
    ],
    'transform-pairs':[
      make('归一化sinc的带宽',s`采用 $\operatorname{sinc}(t)=\sin(\pi t)/(\pi t)$，求 $x(t)=\operatorname{sinc}(2t)$ 的CTFT通带及增益。`,'先明确sinc定义，再应用尺度性质。',[s`$\operatorname{sinc}(t)$ 对应 $|\omega|<\pi$ 内增益1的矩形谱。`,s`时间压缩2倍使频带扩至 $|\omega|<2\pi$。`,s`尺度系数使增益变为1/2，边界点取值按逆变换等价约定处理。`],s`$X=1/2$（$|\omega|<2\pi$），带外0。`,['混用 sin t/t 与归一化sinc，带宽差一个π。'],2),
      make('常数与复载波的广义变换对',s`求 $x(t)=3+2e^{j4t}$ 的CTFT，注明使用何种意义。`,'持续非衰减信号用冲激谱，不当普通绝对收敛积分。',[s`常数1的分布变换为 $2\pi\delta(\omega)$。`,s`复载波 $e^{j4t}$ 变换为 $2\pi\delta(\omega-4)$。`,s`利用线性性，把两条谱线分别乘原系数3和2再相加。`],s`$X=6\pi\delta(\omega)+4\pi\delta(\omega-4)$（分布意义）。`,['复载波只有+4谱线，不能再添一条−4谱线。'],2),
      make('离散Parseval检查归一化',s`$x[n]=\delta[n]+\delta[n-1]$。用时域与DTFT两种方式求能量。`,'频域积分带1/(2π)，并使用模平方。',[s`时域只有两个单位样本，所以 $E=2$。`,s`$X=1+e^{-j\omega}$，$|X|^2=2+2\cos\omega$。`,s`$E=(2\pi)^{-1}\int_{-\pi}^{\pi}(2+2\cos\omega)d\omega=2$。`],s`两种方式均得到 $E=2$。`,['漏掉频域能量等式中的1/(2π)。'],1),
      make('连续Parseval与双边指数',s`对 $x(t)=e^{-|t|}$，用Parseval求 $\int_{-\infty}^{\infty}4/(1+\omega^2)^2d\omega$。`,'先在时域求简单能量，再反推频域积分。',[s`$E=2\int_0^\infty e^{-2t}dt=1$。`,s`其CTFT为 $2/(1+\omega^2)$，模平方正是被积函数。`,s`Parseval给 $1=(1/(2\pi))\int|X|^2d\omega$。`],s`所求积分为 $2\pi$。`,['将时域面积2误作能量1。'],2)
    ],
    'magnitude-phase':[
      make('相同级数幅度谱不唯一确定波形',s`比较 $x(t)=\cos t+\cos2t$ 与 $y(t)=\cos t-\cos2t$ 的CTFS幅度谱。`,'用级数系数的模避免对Dirac分布直接取绝对值。',[s`两信号在 $k=\pm1$ 系数均为1/2。`,s`$k=\pm2$ 系数分别为1/2与−1/2，但模相同。`,s`$t=0$ 时两信号分别为2与0，说明相位差改变了波形。`],s`级数幅度谱相同，二次谐波相位相差π，波形不同。`,['认为幅度谱已经包含完整时域信息。'],2,'fourier'),
      make('实奇信号给纯虚奇频谱',s`求 $x(t)=\delta(t-1)-\delta(t+1)$ 的频谱，并检查实奇对称性。`,'直接变换后用正弦恒等式化简。',[s`$X=e^{-j\omega}-e^{j\omega}$。`,s`欧拉公式给 $X=-2j\sin\omega$，纯虚且关于ω奇对称。`,s`它满足实信号共轭关系 $X(-\omega)=X^*(\omega)$。`],s`$X=-2j\sin\omega$。`,['实信号并不意味着频谱处处实数。'],1),
      make('由线性相位读取纯延时',s`两信号频谱幅度相同，且在非零谱区间有展开相位差 $\phi_y-\phi_x=-4\omega$。若已知二者仅相差时间平移，求平移量。`,'在已声明纯延时模型下比较相位斜率。',[s`$y(t)=x(t-t_0)$ 对应因子 $e^{-j\omega t_0}$。`,s`其展开相位差为 $-\omega t_0$。`,s`与给定斜率−4比较得 $t_0=4$。`],s`延时4个时间单位。`,['仅看主值相位跳变而未展开，或没有纯延时前提就推断唯一波形。'],2),
      make('负实频谱的相位分支',s`在某频点 $X=-2$，主相位可以怎样写？若在另一频点 $X=0$ 呢？`,'负实轴的±π等价，零点没有唯一相位。',[s`$-2=2e^{j\pi}=2e^{-j\pi}$，两角相差2π。`,s`使用 $(-\pi,\pi]$ 约定时选π；其他约定可选−π。`,s`零复数可乘任意角而仍为0，故零点相位未定义。`],s`−2幅度2、相位π模2π；0的相位未定义。`,['把主值分支选择差异当成数学错误。'],1)
    ],
    'frequency-response':[
      make('两个输入频率分别处理',s`$H(j\omega)=1/(1+j\omega)$，持续输入 $x(t)=2+\cos t$。求输出。`,'把直流与正弦分别乘对应频率增益。',[s`直流 $H(0)=1$，输出常数仍为2。`,s`在ω=1处，幅度增益 $1/\sqrt2$，相位 $-\pi/4$。`,s`线性叠加两个分量，持续输入不另加接通暂态。`],s`$y(t)=2+\tfrac1{\sqrt2}\cos(t-\pi/4)$。`,['对所有频率使用同一个数值增益。'],2,'fourier'),
      make('离散一阶IIR的正弦响应',s`因果 $h[n]=0.5^nu[n]$，持续输入 $\cos(\pi n/2)$，求输出。`,'在ω=π/2计算复增益并取幅相。',[s`$H=1/(1-0.5e^{-j\pi/2})=1/(1+0.5j)$。`,s`幅度为 $2/\sqrt5$，相位为 $-\arctan(1/2)$。`,s`输出保留输入离散频率，只改变幅度与相位。`],s`$y[n]=\frac2{\sqrt5}\cos(\pi n/2-\arctan(1/2))$。`,['把e的负指数在π/2处算成+j。'],2),
      make('二阶系统的特定频率响应',s`稳定因果系统 $H(s)=1/(s^2+s+1)$，输入持续 $3\cos t$。求输出。`,'代入虚轴得到同频复增益。',[s`极点实部为−1/2，因果ROC包含虚轴。`,s`$H(j)=1/(-1+j+1)=1/j=-j$。`,s`增益模1，相位−π/2，所以输出为 $3\cos(t-\pi/2)$。`],s`$y(t)=3\sin t$。`,['将分母中的(jω)²错误写成+ω²。'],2,'poles'),
      make('纯延时的群延迟',s`$h[n]=\delta[n-3]$，求频率响应、幅度与展开相位斜率。`,'移位冲激直接给出纯线性相位。',[s`$H(e^{j\omega})=e^{-j3\omega}$。`,s`模恒为1，所有频率幅度不变。`,s`展开相位为 $-3\omega$，群延迟 $-d\phi/d\omega=3$ 样本。`],s`单位幅度响应，延时3拍。`,['主相位包裹跳变处不可直接当作无限群延迟。'],2)
    ],
    'filtering':[
      make('理想低通对多频输入的选择',s`理想低通在 $|\omega|<3$ 增益1，持续输入 $\cos t+2\cos4t$，求输出。`,'逐个比较频率是否位于通带。',[s`ω=±1位于通带，第一项原样保留。`,s`ω=±4位于阻带，第二项被消除。`,s`输入频率避开截止边界，所以不涉及边界取值约定。`],s`$y(t)=\cos t$。`,['用时域振幅大小代替频率判断滤波效果。'],1,'fourier'),
      make('一阶差分的高通特征',s`$y[n]=x[n]-x[n-1]$，求对常数1及 $(-1)^n$ 的输出。`,'分别代入直流和奈奎斯特频率。',[s`常数相邻样本相等，差分为0。`,s`$(-1)^{n-1}=-(-1)^n$，因此差分为 $2(-1)^n$。`,s`等价频率响应 $H=1-e^{-j\omega}$，直流0、π处2。`],s`两输出分别0与 $2(-1)^n$。`,['认为差分器总是把所有输入衰减。'],1),
      make('调制与同步解调',s`$m(t)=\cos t$，先乘 $\cos10t$，再乘 $2\cos10t$，最后经截止3 rad/s的单位理想低通。求最终输出。`,'用两次乘积恒等式追踪基带和高频项。',[s`两次载波相乘给 $2\cos^210t=1+\cos20t$。`,s`低通前为 $\cos t+\tfrac12\cos21t+\tfrac12\cos19t$。`,s`截止3只保留频率1分量，去掉19与21。`],s`最终恢复 $m(t)=\cos t$。`,['第二次载波未乘2而产生一半的基带幅度。'],2,'fourier'),
      make('理想滤波的BIBO前提',s`理想低通 $h(t)=\sin t/(\pi t)$ 是否绝对可积？能否直接称为BIBO稳定？`,'考察远处一系列正面积，不依靠正负抵消。',[s`在每个周期中选 $|\sin t|\ge1/2$ 的固定长度子区间。`,s`第k个这样的区间中 $1/t$ 的数量级为1/k，所以绝对面积下界为常数乘1/k。`,s`调和级数发散，因此 $\int|h|$ 发散，普通卷积系统不满足BIBO判据。`],s`不绝对可积；精确理想低通不能无条件称为BIBO稳定。`,['将sinc的带符号积分收敛当成绝对可积。'],3)
    ],
    'gibbs':[
      make('只有基波时的过冲比例',s`标准±1方波仅保留第一个正弦谐波 $x_1=4\sin t/\pi$。求峰值及相对跳变高度2的超出比例。`,'有限项的过冲不等于无限项极限常数。',[s`在 $t=\pi/2$ 正弦取1，峰值为 $4/\pi$。`,s`超出高电平1的量为 $4/\pi-1$。`,s`除以跳变高度2，比例为 $(4/\pi-1)/2\approx0.13662$。`],s`峰值约1.27324，比例约13.662%；不是吉布斯极限8.949%。`,['把8.949%套用于任意有限谐波数的每个峰值。'],2,'fourier'),
      make('不对称跳变的收敛值',s`分段光滑周期波在某点左极限为−1、右极限为3。傅里叶级数在此点收敛到什么？若教材图在该单点标3呢？`,'级数系数由积分决定，不受单点任意赋值影响。',[s`满足通常收敛条件时，跳变点值为左右极限平均。`,s`$(-1+3)/2=1$。`,s`只修改该单点值不改变积分系数，因此不能强迫级数在该点等于3。`],s`收敛值为1。`,['把人为指定的单点高度误当成跳变点级数和。'],1),
      make('方波基波保留多少平均功率',s`标准±1方波总功率为1。仅保留 $4\sin t/\pi$ 时，功率与均方误差各多少？`,'正交谐波使遗漏能量可从总功率中相减。',[s`幅度A正弦的功率为 $A^2/2$。`,s`基波功率 $P_1=8/\pi^2\approx0.81057$。`,s`误差与保留谐波正交，均方误差为 $1-P_1$。`],s`保留约81.057%功率；均方误差约0.18943。`,['把峰值过冲与全周期均方误差当成同一指标。'],2),
      make('增加谐波仍无法恢复任意单点',s`标准奇方波原点两侧为−1和1，但人为定义 $x(0)=100$。增加谐波能否使原点级数和趋于100？`,'积分系数对单点修改不敏感。',[s`改变有限个时刻的函数值不改变一个周期积分。`,s`所以所有傅里叶系数都与通常方波相同。`,s`其奇次正弦部分和在0处每项为0，极限仍为左右平均0。`],s`不能；原点级数和为0，与指定的100无关。`,['将傅里叶收敛理解为在所有单点都恢复任意赋值。'],2)
    ]
  });
  Object.assign(byTopic,{
    'sampling-process':[
      make('常数采样后的冲激列权重',s`$x(t)=2$，$T_s=1/4$。写理想采样信号及其CTFT。`,'先保留每个样本的冲激权重，再变换周期冲激列。',[s`每个采样值均为2，故 $x_s(t)=2\sum_n\delta(t-n/4)$。`,s`采样角频率 $\omega_s=2\pi/T_s=8\pi$。`,s`周期冲激列变换系数 $2\pi/T_s=8\pi$，再乘输入幅度2。`],s`$X_s(j\omega)=16\pi\sum_k\delta(\omega-8\pi k)$。`,['把样本幅度2与频域冲激列系数混在一起而漏乘。'],2,'sampling'),
      make('频谱重叠时需要相加',s`$X(f)=\max(1-|f|/100,0)$，采用以Hz为变量的变换；$f_s=150$ Hz。求理想采样谱在 $f=75$ Hz 的值。`,'在给定频点列出所有非零频谱副本。',[s`理想采样谱 $X_s(f)=f_s\sum_kX(f-kf_s)$。`,s`在75 Hz，k=0和k=1分别访问75与−75，两值都是1/4；其他副本为0。`,s`将两份相加后再乘150。`],s`$X_s(75)=150(1/4+1/4)=75$。`,['频谱重叠后只画其中一份，而未做复数叠加。'],2,'sampling'),
      make('采样网格偏移引入副本相位',s`令 $p(t)=\sum_n\delta(t-n/2-1/8)$。求其CTFT的冲激权重。`,'把偏移网格视为周期冲激列的整体延时。',[s`原周期为1/2，角频率间隔 $\omega_s=4\pi$，每条权重为 $4\pi$。`,s`延时1/8使第k条谱线乘 $e^{-jk\omega_s/8}$。`,s`因此相位因子为 $e^{-jk\pi/2}$，模不变。`],s`$P(j\omega)=4\pi\sum_ke^{-jk\pi/2}\delta(\omega-4\pi k)$。`,['认为移动采样网格只改变时域图，不影响频域相位。'],3),
      make('序列DTFT与冲激采样CTFT的坐标对应',s`$x[n]=x_c(nT_s)$。从定义推导 $X_s(j\Omega)$ 与 $X_d(e^{j\omega})$ 的关系。`,'两者都是对相同样本求和，区别在频率坐标。',[s`冲激采样CTFT为 $X_s(j\Omega)=\sum_nx[n]e^{-j\Omega nT_s}$。`,s`序列DTFT为 $X_d(e^{j\omega})=\sum_nx[n]e^{-j\omega n}$。`,s`令 $\omega=\Omega T_s$ 即相同；DTFT的2π周期映射成CTFT的 $2\pi/T_s$ 周期。`],s`$X_s(j\Omega)=X_d(e^{j\Omega T_s})$，此等式本身不另乘1/Ts。`,['把频谱复制公式中的1/Ts重复乘到此定义对应式上。'],2)
    ],
    'nyquist':[
      make('多个模拟频率的采样下限',s`$x(t)=\cos(2\pi120t)+2\sin(2\pi450t)$。按一般基带采样定理选择一个保证恢复的整数Hz采样率。`,'最高频率决定充分条件，不是频率之和。',[s`最高频率为450 Hz。`,s`普通带限采样的严格充分条件为 $f_s>900$ Hz。`,s`例如取1000 Hz，奈奎斯特频率500 Hz，高于所有输入分量。`],s`可取1000 Hz；一般保证条件 $f_s>900$ Hz。`,['把120+450作为最高频率，或把临界等号当无条件保证。'],1,'sampling'),
      make('临界频率的相位信息丢失',s`以 $f_s=2f_0$ 采样 $A\cos(2\pi f_0t+\phi)$，为何不能对未知A和φ无条件恢复？`,'在临界采样时展开整数π的三角式。',[s`样本为 $A\cos(\pi n+\phi)=A(-1)^n\cos\phi$。`,s`只能观测乘积 $A\cos\phi$，无法独立确定幅度与相位。`,s`特别地φ=π/2时全部样本为0，非零正弦与零信号无法区分。`],s`临界等号可能丢失整条正弦的相位与幅值信息。`,['只用φ=0的余弦图就宣称等号对任意相位成立。'],2,'sampling'),
      make('抗混叠滤波器应放在哪里',s`ADC以800 Hz采样，模拟输入含100 Hz有用分量和700 Hz干扰。数字低通能否把混叠后的干扰与有用分量分开？`,'先计算干扰采样后的基带等价频率。',[s`700−800=−100 Hz，实余弦干扰折叠到100 Hz。`,s`它与有用100 Hz分量占据同一离散频率，普通数字滤波无法区分来源。`,s`应在ADC前使用模拟低通保留100 Hz并抑制700 Hz，使带外能量不进入采样。`],s`须在采样前抗混叠；采样后不能无条件分离同频重叠信息。`,['以为采样后再低通就能撤销已经发生的混叠。'],2),
      make('一般带限定理与已知模型不同',s`已知输入严格属于 $x(t)=A\cos(2\pi300t)$ 且只有实数A未知。以100 Hz采样能否确定A？这是否推翻采样定理？`,'区分任意带限信号类与只有一个未知参数的受限模型。',[s`采样得 $x[n]=A\cos(6\pi n)=A$，所以任一无噪样本即可确定A。`,s`这依赖预先知道频率和相位，仅剩一个未知系数。`,s`一般带限信号类还含零频等其他信号，同样样本不能区分，普通唯一恢复保证仍不成立。`],s`在给定受限模型上能求A；不构成对一般采样定理的反例。`,['把充分条件误说成任意先验模型下都必须满足的必要条件。'],3)
    ],
    'aliasing':[
      make('多次折回后的余弦混叠频率',s`1300 Hz余弦以800 Hz采样，求 $[0,400]$ Hz内的等价频率。`,'先减整数倍采样率，再利用余弦偶性。',[s`1300−2×800=−300 Hz，落入基本有符号区间。`,s`样本为 $\cos(-2\pi300n/800)$。`,s`余弦为偶函数，因此与+300 Hz余弦相同。`],s`混叠为300 Hz。`,['只减一次采样率后得到500 Hz就停止折回。'],1,'sampling'),
      make('正弦混叠要保留符号',s`700 Hz正弦以1000 Hz采样，写出基带等价序列，不能只给频率。`,'负频率对正弦会产生负号。',[s`$x[n]=\sin(1.4\pi n)$。`,s`减去每拍2π后得到 $\sin(-0.6\pi n)$。`,s`利用正弦奇性，等于 $-\sin(0.6\pi n)$。`],s`等价为−300 Hz正弦，或300 Hz正弦再加π相位。`,['对正弦直接取混叠频率绝对值而不修正相位。'],2,'sampling'),
      make('非零连续信号采样后全为零',s`$x(t)=\sin(2\pi100t)+\sin(2\pi900t)$，以1000 Hz采样，求序列。`,'两个分量折回后可能相互抵消。',[s`100 Hz项给 $\sin(0.2\pi n)$。`,s`900 Hz项给 $\sin(1.8\pi n)=-\sin(0.2\pi n)$。`,s`相加后每个整数样本都为0，而连续时间两项并非恒等抵消。`],s`$x[n]=0$ 对所有整数n。`,['假定混叠后的各幅度只能相加而不能按相位抵消。'],2),
      make('复指数需要有符号频率代表',s`将 $e^{j11\pi n/6}$ 的角频率折回 $[-\pi,\pi)$，它是否等于 $e^{j\pi n/6}$？`,'对复指数只按2π同余，不额外应用余弦偶性。',[s`$11\pi/6-2\pi=-\pi/6$。`,s`所以原序列等于 $e^{-j\pi n/6}$。`,s`在n=1两者虚部符号相反，不能等同于正频率复指数。`],s`基本代表为 $-\pi/6$ rad/sample；与正π/6一般不同。`,['把实余弦的±频率等价套给复指数。'],2)
    ],
    'reconstruction':[
      make('重建低通需要补偿采样增益',s`$T_s=0.2$ s，已知模拟信号严格带限在 $|\omega|<10$ rad/s。理想冲激采样后选择怎样的重建低通？`,'先比较采样角频率，再补偿复制幅度。',[s`$\omega_s=2\pi/0.2=10\pi>20$，满足严格不重叠。`,s`可在信号带宽10与最近副本边缘 $10\pi-10$ 之间选择截止，例取 $\pi/T_s=5\pi$。`,s`通带增益取 $T_s=0.2$，抵消采样谱中的1/Ts。`],s`可取 $H_r=0.2$ 在 $|\omega|<5\pi$，带外0。`,['重建低通增益误设为1，恢复幅度被放大5倍。'],2,'sampling'),
      make('两个样本的有限sinc插值',s`样本间隔1，仅保留 $x[0]=1,x[1]=-1$ 两项，计算有限插值在 $t=0,1/2,1$ 的值。`,'直接计算两个移动sinc核；不把有限插值宣称为任意原信号。',[s`$\hat x(t)=\operatorname{sinc}(t)-\operatorname{sinc}(t-1)$。`,s`在0与1处，另一核在非零整数位置为0，结果分别1、−1。`,s`在1/2处，两核因sinc偶性相等，结果为0。`],s`三个值为 $[1,0,-1]$。`,['把只有两个样本的插值结果当成无限样本理想重建保证。'],1,'sampling'),
      make('零阶保持与理想重建的差别',s`零阶保持核 $h_0(t)=u(t)-u(t-T_s)$。求频率响应，并在 $T_s=0.1$、$\omega=5\pi$ 时给出相对直流的幅度与相位。`,'保持器核是矩形，频谱有sinc下垂和半拍延时。',[s`积分得 $H_0=T_se^{-j\omega T_s/2}\operatorname{sinc}(\omega T_s/(2\pi))$。`,s`相对直流增益为 $\sin(\pi/4)/(\pi/4)=2\sqrt2/\pi$。`,s`此频点sinc为正，相位为 $-\omega T_s/2=-\pi/4$。`],s`相对增益约0.90032，相位−π/4；保持器不是理想平坦低通。`,['把连接成台阶的保持输出当作精确sinc重建。'],3),
      make('穿过全部样本仍不保证原信号',s`以 $T_s=1$ 采样。比较 $x_1(t)=0$ 与 $x_2(t)=\sin2\pi t$，说明为何不能只凭“插值经过所有点”证明重建正确。`,'先检查样本相同，再检查带限前提。',[s`两信号在每个整数时刻都为0。`,s`零样本的sinc插值为0，确实经过所有样本。`,s`但第二信号含1 Hz分量，超过0.5 Hz奈奎斯特频率，不属于可唯一恢复的带限类。`],s`没有带限等先验时，同一组样本可对应不同连续波形。`,['只检查采样点误差为0，而不检查信号类与采样率条件。'],2)
    ],
    'laplace-bilateral':[
      make('正向增长信号仍可有拉普拉斯变换',s`求 $e^{3t}u(t)$ 的双边拉普拉斯变换并判断普通绝对收敛CTFT。`,'指数权重必须压过信号增长。',[s`积分变成 $\int_0^\infty e^{-(s-3)t}dt$。`,s`要求 $\operatorname{Re}s>3$，积分值 $1/(s-3)$。`,s`虚轴不在ROC内，所以不存在普通绝对收敛CTFT。`],s`$X=1/(s-3)$，ROC为实部大于3。`,['把代数式可在jω处求值当成原积分收敛。'],1,'poles'),
      make('左边指数的符号与ROC',s`求 $x(t)=e^{2t}u(-t)$ 的双边变换。`,'负无穷端要求指数向左衰减，分母符号随积分端点决定。',[s`$X=\int_{-\infty}^0e^{(2-s)t}dt$。`,s`负无穷端消失要求 $\operatorname{Re}(2-s)>0$。`,s`积分给 $1/(2-s)$，不是 $1/(s-2)$。`],s`$X=-1/(s-2)$，ROC：$\operatorname{Re}s<2$。`,['只记分母形式，漏掉左边积分产生的负号。'],2),
      make('双边信号需要ROC取交集',s`求 $x(t)=e^{-2t}u(t)+e^tu(-t)$ 的双边变换及ROC。`,'分别计算两半轴，再取共同收敛区域。',[s`右边项为 $1/(s+2)$，ROC实部大于−2。`,s`左边项为 $1/(1-s)$，ROC实部小于1。`,s`两项相加必须同时收敛，故条带 $-2<\operatorname{Re}s<1$。`],s`$X=1/(s+2)+1/(1-s)$，ROC为上述条带，包含虚轴。`,['把两项ROC并起来，而不是取交集。'],2,'poles'),
      make('垂直线上的值是加权傅里叶变换',s`$x=e^tu(t)$。解释 $X(2+j\omega)$ 为何等于 $1/(1+j\omega)$。`,'把s的实部权重与傅里叶振荡分开。',[s`$x(t)e^{-2t}=e^{-t}u(t)$，它绝对可积。`,s`$X(2+j\omega)=\int x(t)e^{-2t}e^{-j\omega t}dt$。`,s`识别为加权信号的CTFT，得到 $1/(1+j\omega)$。`],s`这是 $e^{-t}u(t)$ 的CTFT，不是原增长信号的普通CTFT。`,['忽略垂直线实部不同导致时域指数加权不同。'],2)
    ],
    'laplace-roc':[
      make('一条极点分式的两个时间方向',s`$X(s)=1/(s-2)$，分别给ROC实部大于2和小于2的逆变换。`,'同一分式必须用ROC选择右边或左边。',[s`右边 $e^{2t}u(t)$ 的积分在实部大于2收敛。`,s`左边 $-e^{2t}u(-t)$ 的积分在实部小于2收敛。`,s`后者ROC包含虚轴，而前者不包含，傅里叶存在性不同。`],s`两逆变换依次为 $e^{2t}u(t)$、$-e^{2t}u(-t)$。`,['省去ROC而报告唯一逆变换。'],2),
      make('混合半平面极点也能有稳定ROC',s`$H(s)=1/((s+2)(s-1))$，选择使冲激响应绝对可积的ROC并求h。`,'稳定ROC需包含虚轴，因而选两个极点之间的条带。',[s`分解为 $-\tfrac13/(s+2)+\tfrac13/(s-1)$。`,s`ROC取 $-2<\operatorname{Re}s<1$，第一项右边、第二项左边。`,s`$h=-\tfrac13e^{-2t}u(t)-\tfrac13e^tu(-t)$，绝对面积为1/6+1/3。`],s`非因果稳定，绝对面积1/2，ROC为上述条带。`,['有右半平面极点就忽略非因果选择而一律判不稳定。'],3,'poles'),
      make('可去奇点不是真正极点',s`求 $x(t)=e^t[u(t)-u(t-1)]$ 的双边变换及ROC，讨论s=1。`,'有限时间支撑使所有有限复频率都可积分。',[s`$X=\int_0^1e^{-(s-1)t}dt=[1-e^{-(s-1)}]/(s-1)$（s≠1）。`,s`在s=1直接积分为1，也等于表达式极限。`,s`所以s=1为可去奇点，不限制ROC；所有有限s均收敛。`],s`ROC为整个有限s平面，$X(1)=1$。`,['见到分母s−1就机械认定存在极点。'],3),
      make('没有共同ROC时不能机械相乘',s`$x=e^{2t}u(t)$、$h=-e^tu(-t)$。判断普通卷积是否存在，能否直接把两个分式相乘？`,'空ROC交集提示需要回到卷积定义检查。',[s`两变换ROC分别为实部大于2和小于1，交集为空。`,s`固定t时，卷积非零区要求 $\tau\ge\max(0,t)$。`,s`被积函数为 $-e^te^{\tau}$，从有限下限到正无穷积分发散。`],s`普通卷积发散，形式乘积不能作为此卷积的变换。`,['将分式乘法存在误当成时域卷积存在。'],3)
    ],
    'unilateral-laplace':[
      make('单边变换分离常输入与初值',s`$y'+2y=3u(t)$，$y(0^-)=1$，求t≥0响应。`,'导数变换先带出初值项。',[s`$(s+2)Y_+=3/s+1$。`,s`部分分式得 $Y_+=3/(2s)-1/[2(s+2)]$。`,s`逆变换并检查 $y(0^+)=1$、稳态3/2。`],s`$y(t)=3/2-\tfrac12e^{-2t}$（t≥0）。`,['把非零初值项漏掉。'],2),
      make('二阶初速度通过单边变换进入方程',s`$y''+3y'+2y=0$，$y(0^-)=0,y'(0^-)=1$。求t≥0响应。`,'二阶导数的两个边界项必须分别保留。',[s`二阶导数变换为 $s^2Y_+-1$，一阶导数为sY。`,s`因此 $(s+1)(s+2)Y_+=1$。`,s`展开为 $1/(s+1)-1/(s+2)$，逐项逆变换。`],s`$y(t)=e^{-t}-e^{-2t}$（t≥0）。`,['将初速度错乘s，或把初速度项当成输入冲激。'],2),
      make('延时冲激与初始储能同时存在',s`$y'+y=\delta(t-1)$，$y(0^-)=2$，用单边变换求解。`,'初值与延时冲激在代数方程中是不同来源。',[s`$(s+1)Y_+=2+e^{-s}$。`,s`分为 $2/(s+1)$ 与 $e^{-s}/(s+1)$。`,s`第二项使用延时性质，必须同时平移指数和阶跃。`],s`$y(t)=2e^{-t}+e^{-(t-1)}u(t-1)$（t≥0）。`,['把第二项误写为 $e^{-t}u(t-1)$，漏掉幅值匹配。'],2),
      make('单边变换无法恢复整个过去',s`比较零信号与 $x(t)=e^t$（t<0）、$x(t)=0$（t≥0）的单边拉普拉斯变换。`,'单边积分只记录起点之后的信号，单点普通值无积分面积。',[s`两个信号在所有t>0处都为0。`,s`它们没有原点冲激，故从0⁻起算的积分均为0。`,s`负时间完整波形不同，说明相同单边变换并不确定全部过去。`],s`二者单边变换均为0；单边变换只用于指定半轴信息。`,['把单边逆变换的唯一性扩张到全实轴信号。'],2)
    ],
    'laplace-inverse':[
      make('完成平方识别阻尼余弦',s`$X(s)=(s+1)/(s^2+2s+5)$，ROC实部大于−1，求逆变换。`,'分母完成平方后对齐余弦标准对。',[s`$s^2+2s+5=(s+1)^2+2^2$。`,s`$\mathcal L\{e^{-t}\cos2t\,u(t)\}=(s+1)/[(s+1)^2+4]$。`,s`右边信号ROC实部大于−1，与题设一致。`],s`$x=e^{-t}\cos2t\,u(t)$。`,['把分母常数5直接当成振荡频率√5而忽略完成平方。'],2,'poles'),
      make('真有理式的留数式展开',s`$X(s)=(s+3)/((s+1)(s+2))$，ROC实部大于−1，求逆变换。`,'在单极点处乘掉相应因子求系数。',[s`$A=\left.(s+3)/(s+2)\right|_{s=-1}=2$。`,s`$B=\left.(s+3)/(s+1)\right|_{s=-2}=-1$。`,s`ROC位于全部极点右侧，两项都用右边指数。`],s`$x=(2e^{-t}-e^{-2t})u(t)$。`,['展开系数符号错误，未通分验证。'],1),
      make('非真有理式包含冲激导数',s`$X(s)=(s^2+2s+3)/(s+1)$，ROC实部大于−1，以分布意义求逆。`,'先多项式长除，再处理普通指数部分。',[s`长除得 $X=s+1+2/(s+1)$。`,s`双边分布变换中 $\delta'\leftrightarrow s$，$\delta\leftrightarrow1$。`,s`剩余真有理项对应 $2e^{-t}u(t)$。`],s`$x=\delta'(t)+\delta(t)+2e^{-t}u(t)$。`,['对非真有理式直接丢掉多项式部分。'],3),
      make('左边重复极点的时间因子',s`$X(s)=1/(s+1)^2$，ROC实部小于−1，求逆变换。`,'从左边单极点变换对用s求导得到重复极点。',[s`左边基本对为 $-e^{-t}u(-t)\leftrightarrow1/(s+1)$。`,s`性质 $\mathcal L\{tx\}=-dX/ds$ 给出 $1/(s+1)^2$。`,s`因此时域为 $t[-e^{-t}u(-t)]$，ROC保持在左半平面。`],s`$x(t)=-te^{-t}u(-t)$。`,['重复极点只背右边公式而无视题设ROC。'],3)
    ],
    'laplace-system':[
      make('极点、零点与直流增益',s`因果 $H(s)=(s+2)/(s^2+2s+5)$，求极点零点、稳定性和单位阶跃最终值。`,'先因式结构和ROC，再求稳定系统的直流增益。',[s`零点为−2，极点由 $(s+1)^2+4=0$ 得 $-1\pm2j$。`,s`因果ROC实部大于−1，包含虚轴，所以外部BIBO稳定。`,s`单位阶跃稳态为 $H(0)=2/5$；极点条件保证相应最终值存在。`],s`零点−2，极点−1±2j，稳定，阶跃最终值2/5。`,['只代s=0求最终值，却不检查稳定与极限条件。'],2,'poles'),
      make('直接通路含冲激但仍可BIBO稳定',s`因果 $H(s)=s/(s+2)$，写h并直接证明BIBO稳定。`,'将直接通路与普通可积核分开，不对δ套普通绝对积分。',[s`$H=1-2/(s+2)$，所以 $h=\delta(t)-2e^{-2t}u(t)$。`,s`输出 $y=x-2(e^{-2t}u*x)$。`,s`若 $|x|\le M$，则 $|y|\le M+2M\int_0^\infty e^{-2t}dt=2M$。`],s`BIBO稳定，上界2M；冲激项按直接通路单独处理。`,['看到δ就错误宣称系统一定不稳定，或写普通函数意义下的δ绝对积分。'],3),
      make('外部传递函数不显示隐藏状态',s`状态方程 $v'=v+x$、$z'=-z+x$，输出 $y=z$。零状态外部映射是否BIBO稳定？内部状态是否都渐近稳定？`,'区分可观测输出与未进入输出的不稳定状态。',[s`零状态外部传递函数为 $H(s)=1/(s+1)$，冲激响应可积。`,s`所以输入到y的映射BIBO稳定。`,s`但在零输入且 $v(0)=1$ 时，$v=e^t$ 增长，因此整个状态模型并非内部渐近稳定。`],s`外部BIBO稳定；内部不渐近稳定。`,['用约分后的外部系统函数代替全部内部状态分析。'],3),
      make('稳定非因果二阶系统',s`$H(s)=1/(s^2-1)$，选稳定ROC并写h。`,'虚轴必须位于两极点之间的条带。',[s`$H=\tfrac12/(s-1)-\tfrac12/(s+1)$。`,s`ROC取 $-1<\operatorname{Re}s<1$，第一项左边、第二项右边。`,s`得到 $h=-\tfrac12e^tu(-t)-\tfrac12e^{-t}u(t)=-\tfrac12e^{-|t|}$（除原点普通约定）。`],s`稳定非因果，绝对面积1，ROC为上述条带。`,['只凭有正实部极点就跳过ROC选择。'],3,'poles')
    ],
    'z-definition':[
      make('有限双边序列的Laurent多项式',s`$x[-1]=2,x[0]=-1,x[2]=3$，其余为0。求Z变换及ROC。`,'每个样本贡献 $x[n]z^{-n}$，并检查0和无穷远。',[s`负索引−1贡献2z，0拍贡献−1，2拍贡献 $3z^{-2}$。`,s`所有有限非零z都只有有限项，故收敛。`,s`正索引项排除z=0，负索引项在扩展复平面上排除无穷远。`],s`$X=2z-1+3z^{-2}$，ROC：$0<|z|<\infty$。`,['负索引对应的z幂符号写反。'],2),
      make('交替衰减序列与单位圆取值',s`求 $(-0.5)^nu[n]$ 的Z变换，并给出DTFT在0与π处的值。`,'先做等比和，再确认单位圆位于ROC。',[s`$X=1/(1+0.5z^{-1})$，ROC $|z|>0.5$。`,s`单位圆在其中，所以可以代 $z=e^{j\omega}$。`,s`ω=0时值2/3，ω=π时分母1−0.5，值2。`],s`$X=z/(z+0.5)$；DTFT两点为2/3与2。`,['没有ROC就直接代单位圆。'],1,'poles'),
      make('提前与延时的端点ROC',s`分别求 $\delta[n-3]$ 与 $\delta[n+2]$ 的Z变换，解释0与无穷远。`,'用定义只保留唯一非零样本。',[s`第一项唯一非零位置n=3，因此变换 $z^{-3}$。`,s`第二项唯一非零位置n=−2，因此变换 $z^2$。`,s`前者排除0而包括无穷远；后者包括所有有限z但排除无穷远。`],s`变换分别 $z^{-3}$、$z^2$，端点ROC如步骤。`,['有限序列不一定在z=0与无穷远同时收敛。'],2),
      make('索引乘法与Z域导数',s`求 $x[n]=n(0.4)^nu[n]$ 的Z变换。`,'对基本等比和逐项求导。',[s`令 $r=0.4z^{-1}$，基本和为 $\sum_{n=0}^\infty r^n=1/(1-r)$。`,s`在 $|r|<1$ 内求导再乘r，得到 $\sum nr^n=r/(1-r)^2$。`,s`换回z并保留 $|z|>0.4$。`],s`$X=0.4z^{-1}/(1-0.4z^{-1})^2$，ROC $|z|>0.4$。`,['将n乘法误写成对z导数而漏掉−z系数。'],2)
    ],
    'z-roc':[
      make('圆环ROC对应双边序列',s`$X(z)=z/(z-0.2)+z/(z-2)$，ROC $0.2<|z|<2$，求序列与稳定性。`,'对两极点分别选择与圆环一致的时间方向。',[s`0.2极点项选右边 $0.2^nu[n]$。`,s`2极点项选左边 $-2^nu[-n-1]$。`,s`圆环包含单位圆，所以序列绝对可和；但负时间有非零样本。`],s`$x=0.2^nu[n]-2^nu[-n-1]$，绝对可和、双边。`,['把两个极点项都选成右边序列。'],2,'poles'),
      make('圆外不稳定与圆内稳定',s`$H(z)=z/(z-2)$，分别比较因果ROC与BIBO稳定ROC。`,'先用单位圆判稳定，再看时间方向。',[s`因果ROC为 $|z|>2$，对应 $2^nu[n]$，不包含单位圆。`,s`稳定ROC为 $|z|<2$，对应 $-2^nu[-n-1]$。`,s`后者绝对和为 $\sum_{m=1}^{\infty}2^{-m}=1$，但非因果。`],s`因果选择不稳定；圆内选择稳定非因果。`,['将极点半径大于1视为任何ROC下都不稳定。'],2),
      make('先约去可去奇点再判断ROC',s`有限序列 $x[n]=\delta[n]$ 的变换也被写成 $(1-z^{-1})/(1-z^{-1})$。z=1是否真正极点？`,'用原序列定义决定解析延拓，而非未约分式的外观。',[s`直接定义给 $X(z)=1$。`,s`未约分式在z=1呈0/0，但约分后的常数在该点有限。`,s`因此该处为可去奇点，不是极点；单位冲激变换在整个扩展平面成立。`],s`z=1不是真正极点，ROC不应因此排除单位圆。`,['把未约分分母的每个根都计为实际极点。'],2),
      make('单位圆上真实极点没有稳定ROC',s`$H(z)=z/(z-1)$。是否能选某个ROC使对应普通离散LTI系统BIBO稳定？`,'稳定ROC必须包含整个单位圆，ROC又不能包含极点。',[s`真实极点在z=1，恰位于单位圆。`,s`任何ROC都必须排除该点。`,s`因此不可能包含整个单位圆，无论选圆内还是圆外都不满足绝对可和。`],s`不能；两种时间方向都不是BIBO稳定。`,['把单位圆边界当作可以纳入ROC的闭圆。'],2,'poles')
    ],
    'z-inverse':[
      make('长除得到直接项与延迟尾部',s`$X(z)=(1+z^{-1})/(1-0.5z^{-1})$，ROC $|z|>0.5$，求逆。`,'先单独处理原点样本，再识别尾部等比展开。',[s`乘开级数 $(1+z^{-1})\sum_{n=0}^{\infty}0.5^nz^{-n}$。`,s`常数项为1；对n≥1，系数为 $0.5^n+0.5^{n-1}=1.5(0.5)^{n-1}$。`,s`用冲激与延迟阶跃把两部分合并。`],s`$x[n]=\delta[n]+1.5(0.5)^{n-1}u[n-1]$。`,['把首拍也代入只适用于n≥1的尾部公式。'],2),
      make('重复极点的有限组合数',s`$X(z)=1/(1-0.5z^{-1})^2$，ROC $|z|>0.5$，求逆并验证前3项。`,'把平方分母看作两个等比序列卷积。',[s`每个因子对应 $0.5^nu[n]$。`,s`n≥0时卷积有n+1项，每项都为 $0.5^n$。`,s`所以 $x[n]=(n+1)0.5^nu[n]$，前三项为1、1、3/4。`],s`$x[n]=(n+1)0.5^nu[n]$。`,['把重复极点逆变换写成n而漏掉+1。'],2),
      make('左边序列延迟后的边界',s`$X(z)=z^{-1}/(1-2z^{-1})$，ROC $|z|<2$，求逆并检查n=0。`,'先逆基本左边对，再整体延迟一拍。',[s`$1/(1-2z^{-1})$ 在圆内对应 $-2^nu[-n-1]$。`,s`乘z⁻¹使序列变为 $-2^{n-1}u[-n]$。`,s`因此n=0处为−1/2；不能沿用延迟前排除0的边界。`],s`$x[n]=-2^{n-1}u[-n]$。`,['延时后只改指数，不改阶跃边界。'],3),
      make('共轭极点还原阻尼正弦',s`$X(z)=0.5z^{-1}/(1+0.25z^{-2})$，ROC $|z|>0.5$，求逆。`,'与阻尼正弦的等比差形式比较。',[s`极点为 $\pm j/2$，对应半径1/2、角度±π/2。`,s`标准求和 $\sum r^n\sin(n\theta)z^{-n}=r\sin\theta\,z^{-1}/(1-2r\cos\theta z^{-1}+r^2z^{-2})$。`,s`取r=1/2、θ=π/2即与题式相同，首项0、次项1/2验证索引。`],s`$x[n]=(1/2)^n\sin(\pi n/2)u[n]$。`,['由复极点角度得到余弦却未检查分子和首拍。'],3,'poles')
    ],
    'z-system-equations':[
      make('三点移动平均的系统函数',s`$y[n]=(x[n]+x[n-1]+x[n-2])/3$，求H与冲激响应，判断稳定性。`,'FIR直接由延时项写出Z域多项式。',[s`零状态变换得到 $Y=(1+z^{-1}+z^{-2})X/3$。`,s`所以 $h=[\delta[n]+\delta[n-1]+\delta[n-2]]/3$。`,s`绝对和为1，有界输入幅度上界不增加，所以BIBO稳定。`],s`$H=(1+z^{-1}+z^{-2})/3$，稳定因果FIR。`,['分子零点位于单位圆不代表系统不稳定。'],1),
      make('零状态阶跃解的有限几何和',s`$y[n]-0.3y[n-1]=u[n]$，$y[-1]=0$。用Z变换或卷积求解。`,'先得到因果冲激响应，再与阶跃求和。',[s`$H=1/(1-0.3z^{-1})$，因果h为 $0.3^nu[n]$。`,s`阶跃输出为 $\sum_{k=0}^{n}0.3^k$。`,s`有限和得 $(1-0.3^{n+1})/0.7$，首拍1、最终10/7。`],s`$y[n]=(1-0.3^{n+1})u[n]/0.7$。`,['只给最终值10/7而没有暂态。'],2),
      make('单边二拍延时公式带两个初值',s`$y[n]-0.5y[n-2]=0$（n≥0），$y[-1]=2,y[-2]=0$。求单边Y及样本。`,'将两个负索引样本明确分离出求和。',[s`$\mathcal Z_+\{y[n-2]\}=z^{-2}Y_++y[-1]z^{-1}+y[-2]$。`,s`因此 $(1-0.5z^{-2})Y_+=z^{-1}$。`,s`展开 $Y_+=z^{-1}\sum_{k=0}^{\infty}0.5^kz^{-2k}$，非零项仅在n=2k+1。`],s`$y[2k]=0$，$y[2k+1]=0.5^k$（k≥0）。`,['二拍延时只保留一个初值项。'],3),
      make('同一差分方程的稳定非因果解',s`方程 $y[n]-2y[n-1]=x[n]$ 能否给出稳定系统？说明需要何种边界约定。`,'方程给分式，因果性或边界条件才选择ROC。',[s`形式系统函数为 $H=1/(1-2z^{-1})$。`,s`若取ROC $|z|<2$，逆变换 $h=-2^nu[-n-1]$，绝对和1。`,s`其 $h[n]-2h[n-1]=\delta[n]$ 可逐点验证，但输出依赖未来，不能因果递推实现。`],s`可以选稳定非因果解；若要求因果则不稳定。`,['把常系数差分方程本身当成完整因果边界条件。'],3)
    ],
    'z-stability-poles':[
      make('圆内重复极点仍可绝对可和',s`因果 $h[n]=(n+1)0.5^nu[n]$，求绝对和并判断稳定。`,'多项式因子不阻止严格指数衰减的可和性。',[s`h非负，绝对和就是 $\sum_{n=0}^{\infty}(n+1)r^n$ 在r=1/2的值。`,s`从几何和求导可得该和为 $1/(1-r)^2$。`,s`代入r=1/2得4，有限，所以BIBO稳定。`],s`绝对和4；对应半径0.5的二重极点仍稳定。`,['见到重复极点就一概判断不稳定。'],2,'poles'),
      make('极点角度与半径分工',s`$h[n]=0.9^n\cos(\pi n/3)u[n]$，证明BIBO稳定，并解释极点角度。`,'用包络上界证稳定，角度只决定振荡频率。',[s`$|h[n]|\le0.9^n$。`,s`绝对和不超过 $1/(1-0.9)=10$。`,s`共轭极点为 $0.9e^{\pm j\pi/3}$，半径控制衰减，角度π/3控制每6拍振荡。`],s`BIBO稳定；绝对和上界10，不声称正好等于10。`,['把余弦绝对值直接替换成1后将上界当成精确值。'],2,'poles'),
      make('自然响应有界不等于BIBO稳定',s`因果冲激响应 $h[n]=\cos(\pi n/3)u[n]$ 有界，系统是否BIBO稳定？`,'稳定条件要求绝对和，不仅是单条响应幅度有界。',[s`h每6拍重复，模为 $[1,1/2,1/2,1,1/2,1/2]$。`,s`每周期绝对和为4，跨无限周期求和发散。`,s`极点在单位圆，符合因果有理系统不满足BIBO稳定的判据。`],s`非BIBO稳定，尽管这条冲激响应逐点有界。`,['把有界自然模式当成所有有界输入都产生有界输出。'],2),
      make('稳定FIR的因果逆可以不稳定',s`$H(z)=1-2z^{-1}$。判断原系统与其因果逆的BIBO稳定性。`,'前向稳定由极点或有限h决定；逆系统把零点变为极点。',[s`原冲激响应 $\delta[n]-2\delta[n-1]$，绝对和3，稳定。`,s`因果逆为 $1/(1-2z^{-1})$，冲激响应 $2^nu[n]$，不稳定。`,s`原系统零点z=2在单位圆外，解释了不能获得稳定因果逆；非因果逆可另选ROC。`],s`原系统稳定；因果逆不稳定。`,['认为前向系统稳定就必有稳定因果逆。'],3,'poles')
    ]
  });
  const byChapter={
    basics:[
      make('综合：单边矩形的奇偶分解与能量',s`$x(t)=u(t)-u(t-2)$。求奇偶分量、各自能量，并验证能量分解（单点取值不影响积分）。`,'用支撑对称关系和奇偶正交性联合检查。',[s`反转后在−2<t<0非零；偶部在 $0<|t|<2$ 为1/2，奇部为 $\operatorname{sgn}(t)/2$。`,s`原矩形宽2、高1，所以 $E_x=2$。`,s`两分量模平方都在总宽4区间为1/4，因此各自能量1。`,s`奇偶交叉项为可积奇函数，全轴积分为0，故总能量等于两部分之和。`],s`$E_x=2=E_e+E_o=1+1$，分量如步骤。`,['在能量叠加时不检查交叉项是否为0。'],2,'transform',V('ct','u(t)-u(t-2)',-3,3)),
      make('综合：采样、周期与功率',s`将 $x_c(t)=1+2\cos(2\pi50t)$ 以300 Hz采样，求序列、基本周期与功率。`,'从单位换算到有限周期平均，形成完整检查链。',[s`$x[n]=1+2\cos(\pi n/3)$。`,s`一个周期样本为 $[3,2,0,-1,0,2]$，最小整数周期6。`,s`平方和为18，除以6得平均功率3。`,s`非零周期序列总能量无限，不属于有限能量信号。`],s`$N_0=6,P=3,E=\infty$。`,['将直流与正弦功率交叉项当成非零平均。'],2,'sampling')
    ],
    systems:[
      make('综合：一个系统检验六种性质',s`对所有双边序列定义 $y[n]=(n+1)x[n-1]$，判断线性、时不变、因果、BIBO稳定、记忆性、可逆性。`,'逐个性质使用自己的定义，不用一个性质替代另一个。',[s`叠加可分配到已知系数，所以线性；延时1检验的系数分别n+1与n，因此时变。`,s`仅访问过去n−1，故因果且有记忆。`,s`有界输入1产生n+1，无界，故非BIBO稳定。`,s`在n=−1系数为0，输入样本x[−2]被完全丢失；例如零输入与δ[n+2]给同一零输出，所以不可逆。`],s`线性、时变、因果、有记忆、非BIBO稳定、不可逆。`,['把系数n+1可形式相除当成所有时刻可逆，漏掉零系数。'],3,'systems'),
      make('综合：滑动积分的性质与信息损失',s`$y(t)=\int_{t-2}^{t}x(v)dv$，定义域为使各有限窗口积分存在的信号。判断线性、时不变、因果、BIBO稳定及一般可逆性。`,'先证明算子性质，再用正弦反例检查信息丢失。',[s`积分线性；延时输入后变量替换得到同延时输出，所以LTI。`,s`只取现在和过去，因果且有记忆。`,s`$|x|\le M$ 时 $|y|\le2M$，所以BIBO稳定。`,s`取非零输入 $x(t)=\cos\pi t$，每个长度2的完整周期积分均为0，与零输入同输出。`],s`LTI、因果、有记忆、BIBO稳定；在此一般输入集合上不可逆。`,['稳定、因果并不保证信息无损。'],3,'systems')
    ],
    lti:[
      make('综合：有限脉冲激发稳定一阶系统',s`$h=e^{-2t}u(t)$，$x=u(t)-u(t-1)$，求输出分段式并判断因果、稳定与最终值。`,'先用卷积确定响应，再从h检查系统性质。',[s`因果支撑使输出在t<0为0。`,s`0≤t<1时，$y=\int_0^te^{-2(t-\tau)}d\tau=(1-e^{-2t})/2$。`,s`t≥1时区间固定为0到1，$y=[e^{-2(t-1)}-e^{-2t}]/2$。`,s`h负时间为0、绝对面积1/2，故因果稳定；脉冲结束后的响应最终衰减至0。`],s`分段式如步骤；系统因果BIBO稳定，输出最终值0。`,['将阶跃最终值1/2套给有限脉冲输入。'],2,'convolution'),
      make('综合：FIR响应的三种算法互验',s`$h[n]=\delta[n]+0.5\delta[n-1]$，输入在0到2为1。用卷积、移位叠加和递推求输出。`,'三种表达都指向同一个零状态LTI映射。',[s`输出公式为 $y[n]=x[n]+0.5x[n-1]$。`,s`逐样本得到 $y[0..3]=[1,1.5,1.5,0.5]$。`,s`也可把三个输入冲激各自生成一份移位h，相加得到同一序列。`,s`h绝对和1.5，故系统稳定；有限输入与有限h使输出带宽索引范围为0到3。`],s`三法均得 $[1,1.5,1.5,0.5]$，其余0。`,['把输出长度错写成输入长度3。'],2,'convolution')
    ],
    fourier:[
      make('综合：多谐波经一阶低通后的功率',s`稳定因果 $H(j\omega)=1/(1+j\omega)$，持续输入 $2+\cos2t+2\sin4t$。求输出和平均功率。`,'各谐波独立幅相变化，功率靠正交关系相加。',[s`直流保持2；ω=2增益 $1/\sqrt5$、相位−arctan2。`,s`ω=4增益 $1/\sqrt{17}$、相位−arctan4，所以第二振荡幅度 $2/\sqrt{17}$。`,s`输出为 $2+\cos(2t-\arctan2)/\sqrt5+2\sin(4t-\arctan4)/\sqrt{17}$。`,s`不同谐波平均交叉项为0，$P_y=4+1/10+2/17$。`],s`$P_y=717/170\approx4.217647$，输出如步骤。`,['功率增益为|H|²，不是|H|。'],3,'fourier'),
      make('综合：移动平均的陷波与周期输出',s`$y[n]=(x[n]+x[n-1])/2$，持续输入 $\cos(\pi n/3)+\cos\pi n$。求输出基本周期与功率。`,'先因式分解频率响应，再分别处理两个谐波。',[s`$H=e^{-j\omega/2}\cos(\omega/2)$。`,s`π处增益0，交替分量消失。`,s`π/3处增益√3/2、相位−π/6，因此 $y=\tfrac{\sqrt3}{2}\cos(\pi n/3-\pi/6)$。`,s`非零离散正弦基本周期6，平均功率为 $(3/4)/2=3/8$。`],s`$N_0=6,P_y=3/8$，输出如步骤。`,['认为滤波后的周期必须仍含所有原输入频率。'],3,'fourier')
    ],
    sampling:[
      make('综合：混叠与采样前滤波决策',s`$x(t)=\cos(2\pi3t)+\cos(2\pi27t)$，以40 Hz采样。求基带等价序列，并说明如何只保留3 Hz分量。`,'先计算发生什么，再选择能阻止信息重叠的处理位置。',[s`3 Hz映到离散角频率3π/20。`,s`27−40=−13 Hz，余弦等价于13 Hz，离散角频率13π/20。`,s`因此样本为两条3 Hz与13 Hz等价分量之和；一般原信号保证恢复需fs>54 Hz。`,s`若目标只要3 Hz，可在采样前用截止10 Hz且能充分抑制27 Hz的模拟低通，再对剩余带限信号采样重建。`],s`$x[n]=\cos(3\pi n/20)+\cos(13\pi n/20)$；预先滤掉27 Hz可保留3 Hz。`,['把混叠出的13 Hz误称为原输入真实分量。'],3,'sampling'),
      make('综合：安全采样到sinc重建的完整链',s`$x(t)=\cos(2\pi3t)$，fs=16 Hz。给出样本、频谱副本中心间距及理想重建式，并说明有限插值的限制。`,'连接模拟Hz、离散角频率和时间核的三个坐标。',[s`$T_s=1/16$，$x[n]=\cos(3\pi n/8)$。`,s`原谱线在±3 Hz，采样后副本位于 $\pm3+16k$ Hz，间距16 Hz。`,s`16>2×3，理想带限条件满足，可用增益1/16的基带重建低通。`,s`$x(t)=\sum_n\cos(3\pi n/8)\operatorname{sinc}(16t-n)$；只有无限和具有该理想结论，有限截断有误差。`],s`样本和重建式如步骤，奈奎斯特频率8 Hz。`,['将采样率16直接当成重建sinc核的宽度16秒。'],2,'sampling')
    ],
    laplace:[
      make('综合：二阶非零初值的总响应',s`$y''+3y'+2y=u(t)$，$y(0^-)=1,y'(0^-)=0$。用单边变换求总响应，并拆成零输入与零状态。`,'先保留所有导数初值项，再独立核对响应分解。',[s`$(s^2+3s+2)Y_+=1/s+s+3$。`,s`展开得 $Y_+=1/(2s)+1/(s+1)-1/[2(s+2)]$。`,s`所以总响应 $y=1/2+e^{-t}-e^{-2t}/2$。`,s`零输入为 $2e^{-t}-e^{-2t}$，零状态为 $1/2-e^{-t}+e^{-2t}/2$；二者相加正确。`,s`检查初值1、初速度0，稳定系统最终值1/2。`],s`$y(t)=1/2+e^{-t}-\tfrac12e^{-2t}$（t≥0）。`,['把给定总响应初值错误地也施加到零状态响应上。'],3,'poles'),
      make('综合：稳定系统也可出现反向阶跃响应',s`因果 $H(s)=(s-1)/((s+1)(s+2))$。判断BIBO稳定性，求单位阶跃响应及初始趋势、最终值。`,'极点决定前向稳定；零点可能改变响应方向。',[s`实际极点−1、−2都在左半平面，因果ROC包含虚轴，所以稳定。`,s`$Y=H/s=-1/(2s)+2/(s+1)-3/[2(s+2)]$。`,s`$y=-1/2+2e^{-t}-3e^{-2t}/2$，初值0。`,s`初始斜率 $-2+3=1>0$，最终 $H(0)=-1/2$；先上升后趋向负值，不能以零点在+1判为前向不稳定。`],s`稳定；阶跃初始上升、最终−1/2，解析式如步骤。`,['将右半平面零点与右半平面极点混为一谈。'],3,'poles')
    ],
    z:[
      make('综合：有限脉冲驱动一阶递归',s`$y[n]-0.5y[n-1]=u[n]-u[n-3]$，$y[-1]=0$。求输出、系统ROC与稳定性。`,'有限输入可用延迟阶跃差，也可直接有限求和。',[s`因果 $H=1/(1-0.5z^{-1})$，ROC |z|>0.5，系统稳定。`,s`0≤n≤2时 $y=\sum_{k=0}^n0.5^k$，得到1、1.5、1.75。`,s`n≥3输入已结束，输出从1.75起每拍减半，$y[n]=1.75(0.5)^{n-2}$。`,s`输入 $X=(1-z^{-3})/(1-z^{-1})$ 在z=1是可去奇点，不应把输出错误地判成有稳态常量。`],s`$y[0..2]=[1,1.5,1.75]$；n≥3按上式衰减至0。`,['有限脉冲的Z式未约分，误把z=1看成真正极点。'],3,'poles'),
      make('综合：双边稳定系统的ROC、响应与直流增益',s`$H(z)=z^2/((z-0.5)(z-2))$，ROC $0.5<|z|<2$。求h、稳定性、因果性及持续常数输入1的输出。`,'把圆环两侧的极点分配到相反时间方向。',[s`部分分式为 $-\tfrac13 z/(z-0.5)+\tfrac43 z/(z-2)$。`,s`按ROC逆变换：$h=-\tfrac13(0.5)^nu[n]-\tfrac43 2^nu[-n-1]$。`,s`绝对和为2/3+4/3=2，单位圆在ROC内，故稳定；负时间非零，故非因果。`,s`常数输出为 $H(1)=1/[(1-0.5)(1-2)]=-2$，也等于全部h之和。`],s`稳定非因果；直流输出恒为−2，h如步骤。`,['把一个圆外极点直接等同于在所有ROC下都不稳定。'],3,'poles')
    ]
  };
  for(const [topic,examples]of Object.entries(byTopic))examples.forEach((item,i)=>{item.id=`worked-${topic}-${i+1}`;});
  for(const [chapter,examples]of Object.entries(byChapter))examples.forEach((item,i)=>{item.id=`integrated-${chapter}-${i+1}`;});
  window.WORKED_EXAMPLES={byTopic,byChapter};
}());
